const renderPlanningCard = (lesson) => `
  <article class="tw-planning-card" data-teacher-search-item>
    <span>${lesson.time}</span>
    <strong>${lesson.title}</strong>
    <small>${lesson.className} · ${lesson.resource}</small>
    <em>${lesson.status}</em>
  </article>
`;

const readTeacherPlanning = () => {
  if (typeof window === "undefined") return [];
  try {
    const parsed = JSON.parse(window.localStorage.getItem(TEACHER_PLANNING_STORAGE_KEY) || "[]");
    return Array.isArray(parsed) ? parsed.filter((item) => item && item.classId === pilotProfiles.class.id) : [];
  } catch (error) {
    return [];
  }
};

const writeTeacherPlanning = (items) => {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(TEACHER_PLANNING_STORAGE_KEY, JSON.stringify(items));
};

const findTeacherPlanningLabel = (collection, value, fallback = "") =>
  collection.find(([key]) => key === value)?.[1] || fallback || value;

const toTeacherIsoDate = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

const fromTeacherIsoDate = (isoDate = "") => {
  const [year, month, day] = String(isoDate).split("-").map(Number);
  return Number.isFinite(year) && Number.isFinite(month) && Number.isFinite(day) ? new Date(year, month - 1, day) : new Date();
};

const getTeacherPlanningWeekStart = (date = new Date()) => {
  const copy = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const day = copy.getDay();
  const diff = day === 0 ? -6 : 1 - day;
  copy.setDate(copy.getDate() + diff);
  return toTeacherIsoDate(copy);
};

const getTeacherPlanningWeekDates = (weekStartIso = teacherPlanningState.weekStartIso || getTeacherPlanningWeekStart()) => {
  const start = fromTeacherIsoDate(weekStartIso);
  return teacherPlanningDays.reduce((dates, [dayKey], index) => {
    const date = new Date(start);
    date.setDate(start.getDate() + index);
    dates[dayKey] = toTeacherIsoDate(date);
    return dates;
  }, {});
};

const formatTeacherPlanningDate = (isoDate = "") => {
  if (!isoDate) return "";
  return fromTeacherIsoDate(isoDate).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
};

const getTeacherPlanningWeekLabel = () => {
  const weekStart = teacherPlanningState.weekStartIso || getTeacherPlanningWeekStart();
  const dates = getTeacherPlanningWeekDates(weekStart);
  return `${formatTeacherPlanningDate(dates.segunda)} a ${formatTeacherPlanningDate(dates.sexta)}`;
};

const getTeacherPlanningClassById = (classId = "") => getTeacherPlanningClasses().find((classItem) => classItem.id === classId) || null;
const getTeacherSelectedPlanningClassId = () => {
  const classes = getTeacherPlanningClasses();
  if (!classes.length) return "";
  if (teacherPlanningState.selectedClassId && classes.some((classItem) => classItem.id === teacherPlanningState.selectedClassId)) {
    return teacherPlanningState.selectedClassId;
  }
  teacherPlanningState.selectedClassId = classes[0]?.id || "";
  return teacherPlanningState.selectedClassId;
};

const getTeacherPlanningClassContext = (classId = "") => {
  const classItem = getTeacherPlanningClassById(classId) || getTeacherPlanningClasses()[0] || null;
  if (!classItem?.id) throw new Error("Nenhuma turma institucional disponivel para o planejamento.");
  const teacherId = classItem.teacherId || teacherInstitutionalState.teacherByClass?.[classItem.id] || teacherInstitutionalState.profile?.teacherId || "";
  if (!teacherId) throw new Error("Vínculo teacher_id não encontrado para esta turma.");
  if (!classItem.schoolId) throw new Error("school_id não encontrado para esta turma.");
  return { classItem, teacherId, schoolId: classItem.schoolId };
};

const normalizeTeacherPlanningResourceType = (value = "") =>
  teacherPlanningRemoteResourceTypes[value] || (Object.values(teacherPlanningRemoteResourceTypes).includes(value) ? value : "outro");

const mapTeacherPlanningResourceType = (value = "") => teacherPlanningLocalResourceTypes[value] || value || "proposta-livre";

const normalizeTeacherPlanningCalendarType = (value = "") => {
  const normalized = normalizeTeacherPlanningResourceType(value);
  return teacherPlanningCalendarTypes.some(([key]) => key === normalized) ? normalized : "outro";
};

const mapTeacherPlanRow = (row = {}, classItem = null, publication = null) => ({
  id: row.id,
  title: row.title || "Proposta sem titulo",
  day: row.weekday || "segunda",
  planDate: row.plan_date || "",
  startTime: row.resource_reference?.start_time || publication?.start_time || "",
  classId: row.class_id || classItem?.id || "",
  className: classItem?.name || "Turma",
  schoolId: row.school_id || classItem?.schoolId || "",
  teacherId: row.teacher_id || classItem?.teacherId || "",
  resourceType: mapTeacherPlanningResourceType(row.resource_type),
  note: row.teacher_notes || "",
  status: row.status || "draft",
  publication,
  published: publication?.status === "published",
  createdAt: row.created_at || "",
  updatedAt: row.updated_at || "",
});

const getTeacherPlanningStatusLabel = (status = "") => {
  if (status === "published") return "FINALIZADO";
  if (status === "archived") return "ARQUIVADO";
  return "RASCUNHO";
};

const setTeacherPlanningError = (message = "") => {
  teacherPlanningState.status = message ? "error" : "ready";
  teacherPlanningState.error = message;
};

const mergeTeacherPlanningRows = (rows = []) => {
  const classById = new Map(getTeacherInstitutionalClasses().map((classItem) => [classItem.id, classItem]));
  const mappedRows = (Array.isArray(rows) ? rows : [rows])
    .filter(Boolean)
    .map((row) => mapTeacherPlanRow(row, classById.get(row.class_id), teacherPlanningState.publicationsByPlanId?.[row.id]));
  if (!mappedRows.length) return;
  const byId = new Map((teacherPlanningState.plans || []).map((plan) => [plan.id, plan]));
  mappedRows.forEach((plan) => byId.set(plan.id, plan));
  teacherPlanningState.plans = Array.from(byId.values());
  teacherPlanningState.status = "ready";
};

const ensureTeacherPlanningWeek = async ({ force = false } = {}) => {
  if (!teacherPlanningState.weekStartIso) teacherPlanningState.weekStartIso = getTeacherPlanningWeekStart();
  if (!force && teacherPlanningState.status === "ready") return teacherPlanningState;
  if (!force && teacherPlanningState.promise) return teacherPlanningState.promise;
  teacherPlanningState.status = "loading";
  teacherPlanningState.error = "";
  teacherPlanningState.promise = (async () => {
    try {
      await ensureTeacherInstitutionalData();
      if (!["ready", "empty"].includes(teacherInstitutionalState.status)) {
        throw new Error(teacherInstitutionalState.error || "Dados institucionais indisponiveis.");
      }
      const classes = getTeacherInstitutionalClasses();
      if (!classes.length) {
        teacherPlanningState.plans = [];
        teacherPlanningState.publicationsByPlanId = {};
        teacherPlanningState.status = "ready";
        return teacherPlanningState;
      }
      const client = createSupabaseRestClient();
      const dates = getTeacherPlanningWeekDates();
      const classIds = classes.map((classItem) => classItem.id).filter(Boolean);
      const planRows = await client.request(
        "teacher_plans",
        `?select=id,teacher_id,class_id,school_id,plan_date,weekday,title,resource_type,resource_reference,teacher_notes,status,created_at,updated_at&status=neq.archived&plan_date=gte.${encodeURIComponent(dates.segunda)}&plan_date=lte.${encodeURIComponent(dates.sexta)}&class_id=${supabaseIn(classIds)}&order=plan_date.asc&order=created_at.asc`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      const planIds = (planRows || []).map((row) => row.id).filter(Boolean);
      const publicationRows = planIds.length
        ? await client.request(
            "class_calendar_entries",
            `?select=id,class_id,school_id,teacher_id,plan_id,entry_date,start_time,end_time,title,description,entry_type,status,created_at,updated_at&status=eq.published&plan_id=${supabaseIn(planIds)}&order=entry_date.asc`,
            { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
          )
        : [];
      const classById = new Map(classes.map((classItem) => [classItem.id, classItem]));
      const publicationsByPlanId = Object.fromEntries((publicationRows || []).filter((row) => row.plan_id).map((row) => [row.plan_id, row]));
      teacherPlanningState.publicationsByPlanId = publicationsByPlanId;
      teacherPlanningState.plans = (planRows || []).map((row) => mapTeacherPlanRow(row, classById.get(row.class_id), publicationsByPlanId[row.id]));
      teacherPlanningState.status = "ready";
      return teacherPlanningState;
    } catch (error) {
      teacherPlanningState.plans = [];
      teacherPlanningState.publicationsByPlanId = {};
      setTeacherPlanningError(error.message || "Falha ao carregar planejamento no Supabase.");
      return teacherPlanningState;
    } finally {
      teacherPlanningState.promise = null;
    }
  })();
  return teacherPlanningState.promise;
};

const saveTeacherPlanningToSupabase = async (formData) => {
  const weekDates = getTeacherPlanningWeekDates();
  const day = String(formData.get("day") || "segunda");
  const existingId = String(formData.get("id") || "");
  const { classItem, teacherId, schoolId } = getTeacherPlanningClassContext(String(formData.get("classId") || ""));
  const startTime = String(formData.get("startTime") || "").trim();
  const currentPlan = existingId ? (teacherPlanningState.plans || []).find((plan) => plan.id === existingId) : null;
  const payload = {
    teacher_id: teacherId,
    class_id: classItem.id,
    school_id: schoolId,
    plan_date: weekDates[day] || weekDates.segunda,
    weekday: day,
    title: String(formData.get("title") || "").trim(),
    resource_type: normalizeTeacherPlanningResourceType(String(formData.get("resourceType") || "proposta-livre")),
    resource_reference: startTime ? { start_time: startTime } : {},
    teacher_notes: String(formData.get("note") || "").trim() || null,
    status: currentPlan && ["draft", "published"].includes(currentPlan.status) ? currentPlan.status : "draft",
  };
  if (!payload.title) throw new Error("Informe um titulo para a proposta.");
  const dayItems = (teacherPlanningState.plans || []).filter((plan) => plan.classId === classItem.id && plan.day === day && plan.id !== existingId && plan.status !== "archived");
  if (dayItems.length >= 5) throw new Error("Cada dia aceita ate 5 itens nesta versao.");
  const client = createSupabaseRestClient();
  let savedRows = [];
  if (existingId) {
    savedRows = await client.request("teacher_plans", `?id=${supabaseEq(existingId)}`, {
      method: "PATCH",
      body: JSON.stringify(payload),
      requireAuthenticated: true,
      allowedRoles: teacherAllowedRoles,
    });
  } else {
    savedRows = await client.request("teacher_plans", "", {
      method: "POST",
      body: JSON.stringify(payload),
      requireAuthenticated: true,
      allowedRoles: teacherAllowedRoles,
    });
  }
  mergeTeacherPlanningRows(savedRows);
  await ensureTeacherPlanningWeek({ force: true });
};

const finalizeTeacherPlanning = async (planId) => {
  const plan = (teacherPlanningState.plans || []).find((item) => item.id === planId);
  if (!plan) throw new Error("Planejamento não encontrado.");
  const client = createSupabaseRestClient();
  await client.request("teacher_plans", `?id=${supabaseEq(planId)}`, {
    method: "PATCH",
    body: JSON.stringify({ status: "published" }),
    requireAuthenticated: true,
    allowedRoles: teacherAllowedRoles,
  });
  await ensureTeacherPlanningWeek({ force: true });
};

const publishTeacherPlanPayload = async (plan) => {
  const { classItem } = getTeacherPlanningClassContext(plan.classId);
  const publication = teacherPlanningState.publicationsByPlanId?.[plan.id] || null;
  const client = createSupabaseRestClient();
  await client.request("rpc/teacher_upsert_calendar_entry", "", {
    method: "POST",
    requireAuthenticated: true,
    allowedRoles: teacherAllowedRoles,
    body: JSON.stringify({
      p_entry_id: publication?.id || null,
      p_plan_id: plan.id,
      p_class_id: classItem.id,
      p_entry_date: plan.planDate,
      p_start_time: plan.startTime || null,
      p_end_time: null,
      p_title: plan.title,
      p_description: plan.note || null,
      p_entry_type: normalizeTeacherPlanningCalendarType(plan.resourceType),
    }),
  });
  await client.request("teacher_plans", `?id=${supabaseEq(plan.id)}`, {
    method: "PATCH",
    body: JSON.stringify({ status: "published" }),
    requireAuthenticated: true,
    allowedRoles: teacherAllowedRoles,
  });
};

const publishTeacherClassWeekToSupabase = async (classId = "") => {
  await ensureTeacherPlanningWeek({ force: true });
  const weekDates = getTeacherPlanningWeekDates();
  const plans = (teacherPlanningState.plans || []).filter(
    (plan) => plan.classId === classId && plan.status !== "archived" && Object.values(weekDates).includes(plan.planDate)
  );
  if (!plans.length) throw new Error("Inclua ao menos um item antes de publicar a semana.");
  teacherPlanningDays.forEach(([day]) => {
    if (plans.filter((plan) => plan.day === day).length > 5) {
      throw new Error("Cada dia aceita ate 5 itens nesta versao.");
    }
  });
  for (const plan of plans) {
    await publishTeacherPlanPayload(plan);
  }
  await ensureTeacherPlanningWeek({ force: true });
};

const archiveTeacherPlanning = async (planId) => {
  const client = createSupabaseRestClient();
  const publication = teacherPlanningState.publicationsByPlanId?.[planId];
  if (publication?.id) {
    await client.request("rpc/teacher_archive_calendar_entry", "", {
      method: "POST",
      requireAuthenticated: true,
      allowedRoles: teacherAllowedRoles,
      body: JSON.stringify({ p_entry_id: publication.id }),
    });
  }
  await client.request("teacher_plans", `?id=${supabaseEq(planId)}`, {
    method: "PATCH",
    body: JSON.stringify({ status: "archived" }),
    requireAuthenticated: true,
    allowedRoles: teacherAllowedRoles,
  });
  await ensureTeacherPlanningWeek({ force: true });
};

const saveTeacherCalendarEntryToSupabase = async (formData) => {
  const planId = String(formData.get("planId") || "");
  const plan = teacherPlanningState.plans.find((item) => item.id === planId);
  if (!plan) throw new Error("Proposta nao encontrada para publicação.");
  const { classItem } = getTeacherPlanningClassContext(plan.classId);
  const payload = {
    p_entry_id: String(formData.get("publicationId") || "") || null,
    p_plan_id: plan.id,
    p_class_id: classItem.id,
    p_entry_date: String(formData.get("entryDate") || plan.planDate),
    p_start_time: String(formData.get("startTime") || "") || null,
    p_end_time: String(formData.get("endTime") || "") || null,
    p_title: String(formData.get("title") || plan.title).trim(),
    p_description: String(formData.get("description") || "").trim() || null,
    p_entry_type: String(formData.get("entryType") || normalizeTeacherPlanningCalendarType(plan.resourceType) || "outro"),
  };
  if (!payload.p_title) throw new Error("Informe um titulo publico para a agenda.");
  const client = createSupabaseRestClient();
  await client.request("rpc/teacher_upsert_calendar_entry", "", {
    method: "POST",
    body: JSON.stringify(payload),
    requireAuthenticated: true,
    allowedRoles: teacherAllowedRoles,
  });
  await ensureTeacherPlanningWeek({ force: true });
};

const archiveTeacherCalendarEntry = async (planId) => {
  const publication = teacherPlanningState.publicationsByPlanId?.[planId];
  if (!publication?.id) return;
  const client = createSupabaseRestClient();
  await client.request("rpc/teacher_archive_calendar_entry", "", {
    method: "POST",
    body: JSON.stringify({ p_entry_id: publication.id }),
    requireAuthenticated: true,
    allowedRoles: teacherAllowedRoles,
  });
  await ensureTeacherPlanningWeek({ force: true });
};

const getTeacherMessageContextByClass = (classId = "") => {
  const classItem = getTeacherInstitutionalClasses().find((item) => item.id === classId) || getTeacherInstitutionalClasses()[0] || null;
  if (!classItem?.id) throw new Error("Turma institucional do aluno nao encontrada.");
  const teacherId = classItem.teacherId || teacherInstitutionalState.teacherByClass?.[classItem.id] || teacherInstitutionalState.profile?.teacherId || "";
  if (!teacherId) throw new Error("Vínculo teacher_id não encontrado para esta turma.");
  if (!classItem.schoolId) throw new Error("school_id não encontrado para esta turma.");
  return { classItem, teacherId, schoolId: classItem.schoolId };
};

const formatTeacherClassMessageDate = (isoDate = "") => {
  if (!isoDate) return "Hoje";
  const date = new Date(isoDate);
  if (Number.isNaN(date.getTime())) return "Hoje";
  return date.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
};

const mapTeacherClassMessage = (row = {}, summary = null) => {
  const classItem = getTeacherInstitutionalClasses().find((item) => item.id === row.class_id) || {};
  const student = row.student_id ? teacherInstitutionalState.studentsById?.[row.student_id] || null : null;
  return {
    id: row.id || "",
    classId: row.class_id || "",
    className: classItem.name || "Turma",
    title: row.title || "Recado",
    text: row.body || row.description || "",
    audienceType: row.audience_type || "class",
    studentId: row.student_id || "",
    studentName: student?.name || "",
    communication_date: row.communication_date || "",
    created_at: row.created_at || "",
    date: formatTeacherClassMessageDate(row.communication_date || row.created_at),
    status: row.status || "published",
    authorRole: row.author_role || "professor",
    deliveredCount: Number(summary?.delivered_count || 0),
    readCount: Number(summary?.read_count || 0),
    unreadCount: Number(summary?.unread_count || 0),
  };
};

const ensureTeacherClassMessages = async ({ force = false, weekStartIso = "", classId = "" } = {}) => {
  if (weekStartIso) teacherClassMessagesState.weekStartIso = weekStartIso;
  if (!teacherClassMessagesState.weekStartIso) teacherClassMessagesState.weekStartIso = getTeacherPlanningWeekStart();
  if (classId) teacherClassMessagesState.classId = classId;
  if (!force && teacherClassMessagesState.status === "ready") return teacherClassMessagesState;
  if (!force && teacherClassMessagesState.promise) return teacherClassMessagesState.promise;
  teacherClassMessagesState.status = "loading";
  teacherClassMessagesState.error = "";
  teacherClassMessagesState.promise = (async () => {
    try {
      await ensureTeacherInstitutionalData();
      if (teacherInstitutionalState.status !== "ready") {
        throw new Error(teacherInstitutionalState.error || "Dados institucionais indisponiveis.");
      }
      const classes = getTeacherInstitutionalClasses();
      if (!teacherClassMessagesState.classId) teacherClassMessagesState.classId = classes[0]?.id || "";
      const selectedClassId = teacherClassMessagesState.classId;
      const classIds = selectedClassId ? [selectedClassId] : classes.map((classItem) => classItem.id).filter(Boolean);
      if (!classIds.length) {
        teacherClassMessagesState.messages = [];
        teacherClassMessagesState.status = "ready";
        return teacherClassMessagesState;
      }
      const client = createSupabaseRestClient();
      const [rows, deliverySummaries] = await Promise.all([
        client.request(
        "communications",
        `?select=id,school_id,author_profile_id,author_role,communication_type,audience_type,class_id,student_id,title,body,communication_date,status,created_at,updated_at&communication_type=eq.message&class_id=${supabaseIn(classIds)}&status=neq.deleted&order=created_at.desc`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
        ),
        communicationDeliverySummariesById(client, teacherAllowedRoles),
      ]);
      teacherClassMessagesState.messages = (rows || []).map((row) => mapTeacherClassMessage(row, deliverySummaries.get(row.id) || null));
      teacherClassMessagesState.status = "ready";
      return teacherClassMessagesState;
    } catch (error) {
      teacherClassMessagesState.error = error.message || "Não foi possível carregar os recados.";
      teacherClassMessagesState.messages = [];
      teacherClassMessagesState.status = "error";
      return teacherClassMessagesState;
    } finally {
      teacherClassMessagesState.promise = null;
    }
  })();
  return teacherClassMessagesState.promise;
};

const sendTeacherClassMessage = async (formData) => {
  await ensureTeacherInstitutionalData();
  const { classItem, schoolId } = getTeacherMessageContextByClass(String(formData.get("classId") || ""));
  const audienceType = String(formData.get("audienceType") || "class");
  const studentId = String(formData.get("studentId") || "");
  const title = String(formData.get("title") || "").trim();
  const body = String(formData.get("message") || "").trim();
  if (!title) throw new Error("Informe o titulo do recado.");
  if (!body) throw new Error("Escreva o recado.");
  if (!["class", "student"].includes(audienceType)) throw new Error("Destino do recado invalido.");
  if (audienceType === "student" && !studentId) throw new Error("Selecione o aluno para o recado individual.");
  if (audienceType === "student" && !getTeacherInstitutionalStudents(classItem.id).some((student) => student.id === studentId)) {
    throw new Error("Aluno fora da turma autorizada.");
  }
  const client = createSupabaseRestClient();
  await client.request("rpc/publish_communication", "", {
    method: "POST",
    body: JSON.stringify({
      p_school_id: schoolId,
      p_communication_type: "message",
      p_audience_type: audienceType,
      p_title: title,
      p_body: body,
      p_class_id: classItem.id,
      p_student_id: audienceType === "student" ? studentId : null,
      p_status: "published",
      p_communication_date: attendanceDefaultDate(),
      p_expires_at: null,
    }),
    requireAuthenticated: true,
    allowedRoles: teacherAllowedRoles,
  });
  await ensureTeacherClassMessages({ force: true });
};

