const renderTeacherEmptyState = (title, text = "") => `
  <div class="tw-empty-state">
    <strong>${printableEscape(title)}</strong>
    ${text ? `<p>${printableEscape(text)}</p>` : ""}
  </div>
`;

const printableEscape = (value) =>
  String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");

const printableNormalize = (value) =>
  String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();

const printableAllowedRoles = ["professor", "aluno", "coordenador", "coordenador_pedagogico", "gestor", "gestor_escolar", "admin", "administrador", "administrador_nacional"];
const printableAdminRoles = ["coordenador", "coordenador_pedagogico", "gestor", "gestor_escolar", "admin", "administrador", "administrador_nacional"];

const getPrintableUserRole = () => {
  try {
    const session = JSON.parse(localStorage.getItem("raizes:supabase-auth-session") || "null");
    const token = session?.access_token || localStorage.getItem("raizes:supabase-access-token") || "";
    const [, payload] = String(token).split(".");
    const decoded = payload ? JSON.parse(atob(payload.replaceAll("-", "+").replaceAll("_", "/"))) : {};
    const metadata = decoded.app_metadata || {};
    const userMetadata = decoded.user_metadata || session?.user?.user_metadata || {};
    return normalizePlatformRole(
      metadata.printable_activities_role ||
        metadata.platform_role ||
        metadata.question_bank_role ||
        metadata.app_role ||
        metadata.role ||
        decoded.platform_role ||
        decoded.app_role ||
        userMetadata.platform_role ||
        userMetadata.role ||
        session?.platform_role ||
        ""
    );
  } catch (error) {
    return "";
  }
};

const canAccessPrintableActivities = ({ admin = false } = {}) => {
  const role = getPrintableUserRole();
  if (role) return (admin ? printableAdminRoles : printableAllowedRoles).includes(role);
  const isDemoAuthenticated = typeof localStorage !== "undefined" && localStorage.getItem(platformAuth.key) === "true";
  const isCurator = typeof localStorage !== "undefined" && localStorage.getItem(platformAuth.curatorKey) === "true";
  return admin ? isCurator : isDemoAuthenticated;
};

const printableActivitiesDataService = (() => {
  const catalog = () => window.RaizesPrintableActivitiesCatalog || { ageGroups: [], bnccFields: [], activities: [] };
  const all = () => (catalog().activities || []).map((item) => ({ visualizacoes: 0, downloads: 0, impressoes: 0, ...item }));
  const visible = ({ admin = false } = {}) =>
    (admin ? all() : all().filter((item) => String(item.status || "").toUpperCase() === "PUBLICADO"))
      .filter((item) => admin || isContentAvailableToSession("activity", item.codigo || item.slug || item.id));
  const storageKey = "raizes:printable-activities:user-state";
  const readUserState = () => {
    try {
      return JSON.parse(localStorage.getItem(storageKey) || '{"favorites":[],"recent":[],"metrics":[]}');
    } catch (error) {
      return { favorites: [], recent: [], metrics: [] };
    }
  };
  const writeUserState = (state) => localStorage.setItem(storageKey, JSON.stringify({ favorites: [], recent: [], metrics: [], ...state }));
  return {
    list: visible,
    getByCode(code, options) {
      return visible(options).find((item) => item.codigo === code || item.slug === code || item.id === code);
    },
    ageGroups: () => catalog().ageGroups || [],
    bnccFields: () => catalog().bnccFields || [],
    facets(items) {
      const unique = (values) => [...new Set(values.flat().filter(Boolean))].sort((a, b) => a.localeCompare(b, "pt-BR"));
      return {
        fields: unique(items.map((item) => item.camposExperiência || [])),
        types: unique(items.map((item) => item.tiposAtividade || [])),
        materials: unique(items.map((item) => item.materiais || [])),
      };
    },
    state: readUserState,
    toggleFavorite(code) {
      const state = readUserState();
      const exists = state.favorites.includes(code);
      state.favorites = exists ? state.favorites.filter((item) => item !== code) : [code, ...state.favorites];
      writeUserState(state);
      return !exists;
    },
    markRecent(code) {
      const state = readUserState();
      state.recent = [code, ...state.recent.filter((item) => item !== code)].slice(0, 12);
      writeUserState(state);
    },
    metric(type, payload = {}) {
      try {
        const state = readUserState();
        state.metrics = [...(state.metrics || []), { type, payload, at: new Date().toISOString() }].slice(-80);
        writeUserState(state);
      } catch (error) {
        return null;
      }
      return null;
    },
  };
})();

const getPrintableParams = () => new URLSearchParams(typeof window === "undefined" ? "" : window.location.search);

const printableIncludes = (item, query) => {
  if (!query) return true;
  const haystack = [
    item.codigo,
    item.titulo,
    item.tema,
    item.objetivo,
    item.orientaçãoProfessor,
    item.descricao,
    item.comandoCriança,
    ...(item.materiais || []),
    ...(item.palavrasChave || []),
    ...(item.tiposAtividade || []),
    ...(item.camposExperiência || []),
  ].join(" ");
  return printableNormalize(haystack).includes(printableNormalize(query));
};

const getPrintableFilteredItems = ({ admin = false } = {}) => {
  const params = getPrintableParams();
  const items = printableActivitiesDataService.list({ admin });
  const query = params.get("q") || "";
  const age = params.get("faixa") || "";
  const field = params.get("campo") || "";
  const type = params.get("tipo") || "";
  const material = params.get("material") || "";
  const favoriteOnly = params.get("favoritos") === "1";
  const userState = printableActivitiesDataService.state();
  const filtered = items.filter((item) => {
    const matchesFavorite = !favoriteOnly || userState.favorites.includes(item.codigo);
    return (
      matchesFavorite &&
      printableIncludes(item, query) &&
      (!age || item.faixaEtaria === age) &&
      (!field || (item.camposExperiência || []).includes(field)) &&
      (!type || (item.tiposAtividade || []).includes(type)) &&
      (!material || (item.materiais || []).includes(material))
    );
  });
  const sort = params.get("ordem") || "relevancia";
  return filtered.sort((a, b) => {
    if (sort === "codigo") return String(a.codigo).localeCompare(String(b.codigo), "pt-BR");
    if (sort === "titulo") return String(a.titulo).localeCompare(String(b.titulo), "pt-BR");
    if (sort === "recentes") return String(b.createdAt || "").localeCompare(String(a.createdAt || ""));
    if (sort === "atualizadas") return String(b.updatedAt || b.dataAtualização || "").localeCompare(String(a.updatedAt || a.dataAtualização || ""));
    if (sort === "visualizadas") return Number(b.visualizacoes || 0) - Number(a.visualizacoes || 0);
    if (sort === "baixadas") return Number(b.downloads || 0) - Number(a.downloads || 0);
    return 0;
  });
};

const renderPrintableAgeCards = ({ admin = false } = {}) => {
  const items = printableActivitiesDataService.list({ admin });
  return `
    <section class="pa-age-grid" aria-label="Faixas etarias">
      ${printableActivitiesDataService
        .ageGroups()
        .map((group) => {
          const count = items.filter((item) => item.faixaEtaria === group.id).length;
          const label = count ? `${count} ATIVIDADES DISPONIVEIS` : "ATIVIDADES EM PRODUCAO";
          return `<button class="pa-age-card" type="button" data-pa-filter-faixa="${group.id}"><span>${group.label}</span><strong>${group.age.toUpperCase()}</strong><small>${label}</small></button>`;
        })
        .join("")}
    </section>
  `;
};

const renderPrintableFilters = ({ admin = false } = {}) => {
  const params = getPrintableParams();
  const items = printableActivitiesDataService.list({ admin });
  const facets = printableActivitiesDataService.facets(items);
  const option = (value, label, selected) => `<option value="${printableEscape(value)}" ${value === selected ? "selected" : ""}>${printableEscape(label || value)}</option>`;
  const options = (values, selected) => `<option value="">Todos</option>${values.map((value) => option(value, value, selected)).join("")}`;
  return `
    <form class="pa-filters" data-pa-filters>
      ${["target", "student", "class"].map((key) => (params.get(key) ? `<input type="hidden" name="${key}" value="${printableEscape(params.get(key))}" />` : "")).join("")}
      <label class="pa-search"><span>Pesquisa</span><input name="q" type="search" value="${printableEscape(params.get("q") || "")}" placeholder="PESQUISE PELO CODIGO, TITULO, TEMA, OBJETIVO, MATERIAL OU PALAVRA-CHAVE" /></label>
      <details class="pa-filter-panel" open>
        <summary>Filtros</summary>
        <div>
          <label><span>Faixa etaria</span><select name="faixa">${options(printableActivitiesDataService.ageGroups().map((group) => group.id), params.get("faixa") || "")}</select></label>
          ${facets.fields.length ? `<label><span>Campo BNCC</span><select name="campo">${options(facets.fields, params.get("campo") || "")}</select></label>` : ""}
          ${facets.types.length ? `<label><span>Tipo</span><select name="tipo">${options(facets.types, params.get("tipo") || "")}</select></label>` : ""}
          ${facets.materials.length ? `<label><span>Material</span><select name="material">${options(facets.materials, params.get("material") || "")}</select></label>` : ""}
          <label><span>Ordenação</span><select name="ordem">
            ${[
              ["relevancia", "Relevancia"],
              ["codigo", "Codigo"],
              ["titulo", "Titulo"],
              ["recentes", "Adicionadas recentemente"],
              ["atualizadas", "Atualizadas recentemente"],
              ["visualizadas", "Mais visualizadas"],
              ["baixadas", "Mais baixadas"],
            ].map(([value, label]) => option(value, label, params.get("ordem") || "relevancia")).join("")}
          </select></label>
          <label class="pa-check"><input name="favoritos" type="checkbox" value="1" ${params.get("favoritos") === "1" ? "checked" : ""} /><span>Somente favoritos</span></label>
          <button type="button" data-pa-clear>Limpar filtros</button>
        </div>
      </details>
    </form>
  `;
};

const printableStatusLabel = (status = "") => {
  const normalized = String(status || "").toUpperCase();
  if (normalized === "PUBLICADO") return "Publicado";
  if (normalized === "RASCUNHO") return "Rascunho";
  if (normalized === "ARQUIVADO") return "Retirado";
  return status || "Não informado";
};

const renderPrintableIndicateButton = (code) =>
  `<button type="button" data-pa-indicate="${printableEscape(code)}">Indicar para</button>`;

const renderPrintableRecommendationDialog = () => {
  const classes = getTeacherInstitutionalClasses();
  const context = getPrintableAssignmentContext();
  const selectedClassId = context.classId && classes.some((item) => item.id === context.classId) ? context.classId : classes[0]?.id || "";
  const selectedStudents = getTeacherInstitutionalStudents(selectedClassId);
  const selectedTarget = context.type === "student" ? "student" : "class";
  return `
    <dialog class="pa-recommendation-dialog" data-pa-recommendation-dialog>
      <form data-pa-recommendation-form>
        <input type="hidden" name="contentId" />
        <input type="hidden" name="contentTitle" />
        <header>
          <div>
            <span>Indicação pedagógica</span>
            <h2>Indicar atividade</h2>
          </div>
          <button type="button" data-pa-recommendation-close aria-label="Fechar">Fechar</button>
        </header>
        ${
          teacherInstitutionalState.status === "ready" && classes.length
            ? `
              <label>
                <span>Turma</span>
                <select name="classId" data-pa-recommendation-class required>
                  ${classes.map((classItem) => `<option value="${printableEscape(classItem.id)}" ${classItem.id === selectedClassId ? "selected" : ""}>${printableEscape(classItem.name)}</option>`).join("")}
                </select>
              </label>
              <label>
                <span>Destino</span>
                <select name="targetType" data-pa-recommendation-target required>
                  <option value="class" ${selectedTarget === "class" ? "selected" : ""}>Toda a turma</option>
                  <option value="student" ${selectedTarget === "student" ? "selected" : ""}>Aluno / Família</option>
                </select>
              </label>
              <label data-pa-recommendation-student-wrap ${selectedTarget === "student" ? "" : "hidden"}>
                <span>Aluno</span>
                <select name="studentId">
                  <option value="">Selecione</option>
                  ${selectedStudents.map((student) => `<option value="${printableEscape(student.id)}" ${student.id === context.id ? "selected" : ""}>${printableEscape(student.name)}</option>`).join("")}
                </select>
              </label>
              <label class="pa-recommendation-note">
                <span>Orientação curta</span>
                <textarea name="note" rows="3" maxlength="280" placeholder="Opcional. Ex.: fazer em casa com apoio da familia."></textarea>
              </label>
              <p data-pa-recommendation-status>Escolha o destino antes de publicar.</p>
              <footer>
                <button type="button" data-pa-recommendation-close>Cancelar</button>
                <button type="submit">PUBLICAR RECOMENDACAO</button>
              </footer>
            `
            : `
              <div class="pa-empty">
                <h2>Turmas reais ainda nao carregadas</h2>
                <p>Entre como professora e aguarde o carregamento dos vinculos institucionais.</p>
              </div>
            `
        }
      </form>
    </dialog>
  `;
};

const renderPrintableActivityCard = (item) => {
  const userState = printableActivitiesDataService.state();
  const isFavorite = userState.favorites.includes(item.codigo);
  const thumb = item.miniatura || item.arquivoPng || item.arquivoOriginal || "";
  const detailParams = appendPrintableContextParams(new URLSearchParams(window.location.search));
  detailParams.set("codigo", item.codigo);
  const backParams = new URLSearchParams(window.location.search);
  backParams.delete("codigo");
  if (backParams.toString()) detailParams.set("voltar", `?${backParams.toString()}`);
  return `
    <article class="pa-card" data-teacher-search-item>
      <div class="pa-thumb">
        ${thumb ? `<img src="${printableEscape(thumb)}" alt="Miniatura da atividade ${printableEscape(item.codigo)}" loading="lazy" decoding="async" />` : `<span>SEM MINIATURA</span>`}
      </div>
      <div class="pa-card-body">
        <mark>${printableEscape(item.codigo)}</mark>
        <h3>${printableEscape(item.titulo || "Titulo pendente")}</h3>
        <p>${printableEscape(item.idade || item.faixaEtaria || "Idade pendente")} · ${printableEscape((item.tiposAtividade || [])[0] || "Tipo pendente")}</p>
        <small>${printableEscape((item.camposExperiência || []).join(", ") || "Campo de experiência pendente")}</small>
        <small><b>Materiais:</b> ${printableEscape((item.materiais || []).slice(0, 3).join(", ") || "pendentes")}</small>
      </div>
      <footer>
        <a href="atividades.html?${detailParams.toString()}" data-pa-view="${printableEscape(item.codigo)}">Visualizar</a>
        ${renderPrintableIndicateButton(item.codigo)}
        <a href="${printableEscape(item.arquivoOriginal || "#")}" download data-pa-download="${printableEscape(item.codigo)}" aria-disabled="${item.arquivoOriginal ? "false" : "true"}">Baixar</a>
        <button type="button" data-pa-print="${printableEscape(item.codigo)}">Imprimir</button>
        <button type="button" data-pa-favorite="${printableEscape(item.codigo)}" aria-pressed="${isFavorite}">${isFavorite ? "Favorito" : "Favoritar"}</button>
      </footer>
    </article>
  `;
};

const renderPrintableMainPage = ({ admin = false } = {}) => {
  if (!canAccessPrintableActivities({ admin })) {
    return `<section class="pa-shell"><div class="pa-empty"><h1>Acesso restrito</h1><p>Este modulo e exclusivo para professor, coordenador, gestor escolar e administrador.</p><a href="login.html?next=${encodeURIComponent(window.location.pathname.split("/").pop() + window.location.search)}">Entrar com perfil autorizado</a></div></section>`;
  }
  if (!admin && isContentGovernanceRequired() && !isContentGovernanceReady()) {
    return `<section class="pa-shell">${renderContentGovernanceLoading("Atividades")}</section>`;
  }
  const params = getPrintableParams();
  const items = getPrintableFilteredItems({ admin });
  const total = printableActivitiesDataService.list({ admin }).length;
  const hasQuery = Boolean([...params.keys()].length);
  return `
    <section class="pa-shell" data-printable-app="${admin ? "admin" : "teacher"}">
      <header class="pa-hero">
        <span>${admin ? "Conteúdos > Atividades Imprimíveis" : "Professor"}</span>
        <h1>Atividades Imprimíveis</h1>
        <p>Encontre, visualize e imprima atividades para apoiar as experiências da Educação Infantil.</p>
        ${admin ? `<a href="README_IMPORTACAO_ATIVIDADES.md">README de importação</a>` : ""}
      </header>
      ${admin ? "" : renderPrintableContextPanel()}
      ${admin ? "" : renderPrintableRecommendationDialog()}
      ${renderPrintableAgeCards({ admin })}
      ${renderPrintableFilters({ admin })}
      <div class="pa-status" role="status">${total ? `${items.length} de ${total} atividades` : "Nenhuma atividade cadastrada ainda. Estrutura pronta para receber o pacote EI2."}</div>
      ${
        admin
          ? `<section class="pa-admin-actions">
              <a href="data/atividades-imprimiveis/modelos/manifest.json">Modelo JSON</a>
              <a href="data/atividades-imprimiveis/modelos/manifest.csv">Modelo CSV</a>
              <code>node scripts/import-printable-activities.mjs --source CAMINHO --dry-run</code>
            </section>`
          : ""
      }
      <section class="pa-grid" aria-label="Atividades imprimiveis">
        ${
          items.length
            ? items.map(renderPrintableActivityCard).join("")
            : `<article class="pa-empty"><h2>${hasQuery ? "Nenhum resultado encontrado" : "Banco vazio"}</h2><p>${hasQuery ? "Ajuste a pesquisa ou limpe os filtros." : "Nenhuma atividade real foi cadastrada nesta etapa."}</p></article>`
        }
      </section>
    </section>
  `;
};

const renderPrintableDetailPage = ({ admin = false } = {}) => {
  if (!admin && isContentGovernanceRequired() && !isContentGovernanceReady()) {
    return `<section class="pa-shell">${renderContentGovernanceLoading("Atividades")}</section>`;
  }
  const code = getPrintableParams().get("codigo");
  const unrestrictedItem = printableActivitiesDataService.getByCode(code, { admin: true });
  if (!admin && unrestrictedItem && !isContentAvailableToSession("activity", unrestrictedItem.codigo || unrestrictedItem.slug || unrestrictedItem.id)) {
    return `<section class="pa-shell">${renderContentUnavailableForSchool({ title: "Atividade indisponivel", type: "activity", id: code })}</section>`;
  }
  const item = printableActivitiesDataService.getByCode(code, { admin });
  if (!item) {
    return `<section class="pa-shell"><div class="pa-empty"><h1>Atividade nao encontrada</h1><p>O codigo informado não existe ou nao esta publicado para este perfil.</p><a href="atividades.html">Voltar ao banco</a></div></section>`;
  }
  printableActivitiesDataService.markRecent(item.codigo);
  printableActivitiesDataService.metric("visualização", { codigo: item.codigo });
  const preview = item.arquivoPng || item.miniatura || item.arquivoOriginal || "";
  const back = getPrintableParams().get("voltar") || "";
  const contextQuery = getPrintableContextQuery();
  const teacherMeta = [
    ["Faixa etaria", item.faixaEtaria],
    ["Idade", item.idade],
    ["Objetivo", item.objetivo],
    ["Orientação", item.orientaçãoProfessor],
    ["Materiais", (item.materiais || []).join(", ")],
    ["Campos de experiência", (item.camposExperiência || []).join(", ")],
    ["Tipo de atividade", (item.tiposAtividade || []).join(", ")],
  ];
  const adminMeta = [
    ["Codigo", item.codigo],
    ["Faixa etaria", item.faixaEtaria],
    ["Idade", item.idade],
    ["Versão", item.versao],
    ["Status", printableStatusLabel(item.status)],
    ["Publicação", item.dataPublicação || "pendente"],
    ["Atualização", item.dataAtualização || item.updatedAt || "pendente"],
    ["Objetivo", item.objetivo],
    ["Campos de experiências", (item.camposExperiência || []).join(", ")],
    ["Direitos de aprendizagem", (item.direitosAprendizagem || []).join(", ")],
    ["Tipo de atividade", (item.tiposAtividade || []).join(", ")],
    ["Materiais", (item.materiais || []).join(", ")],
    ["Orientação ao professor", item.orientaçãoProfessor],
    ["Palavras-chave", (item.palavrasChave || []).join(", ")],
  ];
  return `
    <section class="pa-shell pa-detail" data-printable-app="${admin ? "admin" : "teacher"}">
      <header class="pa-hero">
        <span>${printableEscape(item.codigo)} · ${printableEscape(item.idade || item.faixaEtaria || "Educação Infantil")}</span>
        <h1>${printableEscape(item.titulo || "Titulo pendente")}</h1>
        <p>${printableEscape(item.objetivo || "Atividade pronta para visualização e impressao.")}</p>
        <a href="atividades.html${printableEscape(back || contextQuery)}">Voltar aos resultados</a>
      </header>
      ${renderPrintableContextPanel()}
      ${admin ? "" : renderPrintableRecommendationDialog()}
      <div class="pa-detail-grid">
        <section class="pa-preview">
          ${preview ? `<img src="${printableEscape(preview)}" alt="Visualização ampliada da atividade ${printableEscape(item.codigo)}" />` : `<div class="pa-empty"><h2>Arquivo pendente</h2><p>A atividade ainda não possui arquivo valido associado.</p></div>`}
          <div>
            ${renderPrintableIndicateButton(item.codigo)}
            <a href="${printableEscape(item.arquivoOriginal || "#")}" download data-pa-download="${printableEscape(item.codigo)}">Baixar</a>
            <button type="button" data-pa-print="${printableEscape(item.codigo)}">Imprimir</button>
            <button type="button" data-pa-favorite="${printableEscape(item.codigo)}">Favoritar</button>
          </div>
        </section>
        <aside class="pa-meta">
          ${(admin ? adminMeta : teacherMeta).map(([label, value]) => `<article><strong>${printableEscape(label)}</strong><span>${printableEscape(value || "Não informado")}</span></article>`).join("")}
        </aside>
      </div>
    </section>
  `;
};

const renderPrintableActivitiesPage = ({ admin = false } = {}) =>
  getPrintableParams().get("codigo") ? renderPrintableDetailPage({ admin }) : renderPrintableMainPage({ admin });

const universalActivityEngineVersion = "1.0.0";
const universalActivityStorageKey = "raizes:universal-activity-engine:v1";
const universalActivityStudentProfile = {
  id: pilotProfiles.student.id,
  name: pilotProfiles.student.fullName,
  classId: pilotProfiles.student.classId,
  className: pilotProfiles.student.className,
};

const universalActivityTeacherProfile = {
  id: pilotProfiles.teacher.id,
  name: pilotProfiles.teacher.displayName,
};

const universalActivityToolProfiles = {
  ei2: ["pincel", "dedo", "rolinho", "esponja", "algodao", "papel", "barbante", "bolinhas", "borracha"],
  ei3: ["pincel", "dedo", "rolinho", "esponja", "algodao", "papel", "barbante", "bolinhas", "borracha", "giz", "carimbo", "adesivos", "formas"],
  ei4: ["pincel", "dedo", "rolinho", "esponja", "algodao", "papel", "barbante", "bolinhas", "borracha", "giz", "carimbo", "adesivos", "formas", "lapis", "tracos", "montagem", "arrastar"],
  ei5: ["pincel", "dedo", "rolinho", "esponja", "algodao", "papel", "barbante", "bolinhas", "borracha", "giz", "carimbo", "adesivos", "formas", "lapis", "tracos", "montagem", "arrastar", "letras_moveis", "números", "ordenação", "ligação"],
};

const universalActivityToolLabels = {
  pincel: "Pincel",
  dedo: "Dedo",
  rolinho: "Rolinho",
  esponja: "Esponja",
  algodao: "Algodao",
  papel: "Papel",
  barbante: "Barbante",
  bolinhas: "Bolinhas",
  borracha: "Borracha",
};

const universalActivityDemoClasses = [
  {
    id: pilotProfiles.class.id,
    name: pilotProfiles.class.name,
    students: [
      { id: pilotProfiles.student.id, name: pilotProfiles.student.fullName },
    ],
  },
];

const readUniversalActivityState = () => {
  try {
    return JSON.parse(localStorage.getItem(universalActivityStorageKey) || '{"assignments":[],"submissions":[],"metrics":[]}');
  } catch (error) {
    return { assignments: [], submissions: [], metrics: [] };
  }
};

const writeUniversalActivityState = (state) => {
  localStorage.setItem(universalActivityStorageKey, JSON.stringify({ assignments: [], submissions: [], portfolioRefs: [], metrics: [], ...state }));
};

const getUniversalActivityByCode = (code) => printableActivitiesDataService.getByCode(code, { admin: true });

const getUniversalActivityClass = (classId) => universalActivityDemoClasses.find((item) => item.id === classId) || universalActivityDemoClasses[0];

const getPrintableAssignmentContext = () => {
  const params = getPrintableParams();
  const target = params.get("target") || "";
  if (target === "student") {
    const studentId = params.get("student") || "";
    const classId = params.get("class") || "";
    const classInfo = getTeacherInstitutionalClasses().find((item) => item.id === classId) || null;
    const student = getTeacherInstitutionalStudents(classId).find((item) => item.id === studentId) || teacherInstitutionalState.studentsById?.[studentId] || null;
    return {
      type: "student",
      id: studentId,
      label: student?.name || "Aluno selecionado",
      classId,
      className: classInfo?.name || "Turma selecionada",
      description: `Destino: ${student?.name || "aluno selecionado"}`,
    };
  }
  if (target === "class") {
    const classId = params.get("class") || "";
    const classInfo = getTeacherInstitutionalClasses().find((item) => item.id === classId) || null;
    return {
      type: "class",
      id: classId,
      label: classInfo?.name || "Turma selecionada",
      classId,
      className: classInfo?.name || "Turma selecionada",
      description: `Destino: ${classInfo?.name || "turma selecionada"}`,
    };
  }
  return {
    type: "",
    id: "",
    label: "Não definido",
    classId: universalActivityStudentProfile.classId,
    className: universalActivityStudentProfile.className,
    description: "Sem destino selecionado",
  };
};

const appendPrintableContextParams = (params = new URLSearchParams()) => {
  const context = getPrintableAssignmentContext();
  if (!context.type) return params;
  params.set("target", context.type);
  if (context.type === "student") params.set("student", context.id);
  if (context.classId) params.set("class", context.classId);
  return params;
};

const getPrintableContextQuery = () => {
  const params = appendPrintableContextParams(new URLSearchParams());
  const query = params.toString();
  return query ? `?${query}` : "";
};

const renderPrintableContextPanel = () => {
  const context = getPrintableAssignmentContext();
  return `
    <section class="pa-context-panel" data-pa-context data-target-type="${printableEscape(context.type)}" data-target-id="${printableEscape(context.id)}">
      <div>
        <span>${context.type ? "Indicação pedagógica" : "Atividades imprimiveis"}</span>
        <strong>${printableEscape(context.description)}</strong>
        <small>${context.type ? "Destino preservado para a futura indicação. Nesta etapa a atividade pode ser visualizada e impressa." : "Escolha uma atividade para visualizar, baixar ou imprimir."}</small>
      </div>
      ${context.type ? `<a href="professor.html?view=atividades">Trocar contexto</a>` : ""}
    </section>
  `;
};

const getUniversalActivityTools = (activity, assignment) => {
  const profileKey = assignment?.toolProfile || activity?.perfilFerramentas || activity?.faixaEtaria || "ei2";
  const profileTools = universalActivityToolProfiles[profileKey] || universalActivityToolProfiles.ei2;
  const allowed = activity?.ferramentasPermitidas?.length ? activity.ferramentasPermitidas : profileTools;
  return allowed.filter((tool) => universalActivityToolProfiles.ei5.includes(tool));
};

const getUniversalActivitySuggestedTools = (activity) => {
  if (activity?.ferramentasSugeridas?.length) return activity.ferramentasSugeridas;
  const text = printableNormalize([activity?.titulo, activity?.objetivo, activity?.comandoCriança, ...(activity?.materiais || [])].join(" "));
  const suggestions = [
    ["algodao", "algodao"],
    ["esponja", "esponja"],
    ["rolinho", "rolinho"],
    ["dedo", "dedo"],
    ["barbante", "barbante"],
    ["bolinhas", "bolinha"],
    ["papel", "papel"],
  ];
  return suggestions.filter(([, term]) => text.includes(term)).map(([tool]) => tool);
};

const syncUniversalActivityPortfolio = (submission) => {
  if (submission.status !== "COMPLETED") return;
  const state = readUniversalActivityState();
  const refId = `portfolio-${submission.submissionId}`;
  const portfolioRef = {
    refId,
    submissionId: submission.submissionId,
    assignmentId: submission.assignmentId,
    activityCode: submission.activityCode,
    studentId: submission.studentId,
    classId: submission.classId,
    completedAt: submission.completedAt,
  };
  state.portfolioRefs = [portfolioRef, ...(state.portfolioRefs || []).filter((item) => item.refId !== refId)];
  writeUniversalActivityState(state);
};

const getUniversalActivityPortfolioForStudent = (studentId = universalActivityStudentProfile.id) => {
  const state = readUniversalActivityState();
  const refs = state.portfolioRefs || [];
  return refs
    .filter((ref) => ref.studentId === studentId)
    .map((ref) => ({
      ref,
      submission: state.submissions.find((submission) => submission.submissionId === ref.submissionId),
      assignment: state.assignments.find((assignment) => assignment.assignmentId === ref.assignmentId),
      activity: getUniversalActivityByCode(ref.activityCode),
    }))
    .filter((item) => item.submission);
};

const createUniversalActivityAssignment = ({ activityCode, classId, studentIds, instructions, dueDate, toolProfile, mode }) => {
  const state = readUniversalActivityState();
  const classInfo = getUniversalActivityClass(classId);
  const context = getPrintableAssignmentContext();
  const assignment = {
    assignmentId: `ua-${Date.now()}`,
    activityCode,
    teacherId: universalActivityTeacherProfile.id,
    teacherName: universalActivityTeacherProfile.name,
    classId,
    className: classInfo.name,
    studentIds,
    assignedAt: new Date().toISOString(),
    dueDate: dueDate || "",
    instructions: instructions || "",
    toolProfile: toolProfile || "ei2",
    mode: mode || "livre",
    targetType: context.type || (studentIds.length === classInfo.students.length ? "class" : "student"),
    targetId: context.id || (studentIds.length === classInfo.students.length ? classId : studentIds[0] || classId),
    targetLabel: context.type ? context.label : studentIds.length === classInfo.students.length ? classInfo.name : classInfo.students.filter((student) => studentIds.includes(student.id)).map((student) => student.name).join(", "),
    status: "PUBLICADA",
  };
  state.assignments = [assignment, ...state.assignments.filter((item) => item.assignmentId !== assignment.assignmentId)];
  writeUniversalActivityState(state);
  return assignment;
};

const getUniversalActivityAssignmentsForStudent = (studentId = universalActivityStudentProfile.id) => {
  const state = readUniversalActivityState();
  return state.assignments.filter((assignment) => assignment.status !== "ARQUIVADA" && assignment.studentIds.includes(studentId));
};

const getUniversalActivitySubmission = (assignmentId, studentId = universalActivityStudentProfile.id) => {
  const state = readUniversalActivityState();
  return state.submissions.find((item) => item.assignmentId === assignmentId && item.studentId === studentId) || null;
};

const upsertUniversalActivitySubmission = (submission) => {
  const state = readUniversalActivityState();
  const index = state.submissions.findIndex((item) => item.submissionId === submission.submissionId);
  if (index >= 0) state.submissions[index] = submission;
  else state.submissions.unshift(submission);
  writeUniversalActivityState(state);
  return submission;
};

const getOrCreateUniversalActivitySubmission = (assignment) => {
  const existing = getUniversalActivitySubmission(assignment.assignmentId);
  if (existing) return existing;
  const submission = {
    submissionId: `uas-${assignment.assignmentId}-${universalActivityStudentProfile.id}`,
    assignmentId: assignment.assignmentId,
    activityCode: assignment.activityCode,
    studentId: universalActivityStudentProfile.id,
    studentName: universalActivityStudentProfile.name,
    classId: assignment.classId,
    className: assignment.className,
    teacherId: assignment.teacherId,
    teacherName: assignment.teacherName,
    status: "NOT_STARTED",
    startedAt: "",
    lastSavedAt: "",
    completedAt: "",
    engineVersion: universalActivityEngineVersion,
    canvasData: { strokes: [] },
    objectsData: [],
    preview: "",
    finalArtwork: "",
  };
  return upsertUniversalActivitySubmission(submission);
};

const getUniversalActivityStudentStatus = (assignment) => {
  const submission = getUniversalActivitySubmission(assignment.assignmentId);
  if (!submission || submission.status === "NOT_STARTED") return "NOVA";
  if (submission.status === "COMPLETED") return "CONCLUIDA";
  return "EM ANDAMENTO";
};

const seedUniversalActivityTechnicalAssignments = () => {
  const state = readUniversalActivityState();
  if (state.assignments.some((item) => item.seededBy === "technical-pilot-v1")) return;
  const codes = ["RS-EI2-ATI-001", "RS-EI2-ATI-004", "RS-EI2-ATI-028"].filter((code) => getUniversalActivityByCode(code));
  const seeded = codes.map((code, index) => ({
    assignmentId: `ua-pilot-${String(index + 1).padStart(2, "0")}`,
    activityCode: code,
    teacherId: universalActivityTeacherProfile.id,
    teacherName: universalActivityTeacherProfile.name,
    classId: universalActivityStudentProfile.classId,
    className: universalActivityStudentProfile.className,
    studentIds: [universalActivityStudentProfile.id],
    assignedAt: new Date().toISOString(),
    dueDate: "",
    instructions: index === 0 ? "Use pintura livre para testar o motor." : index === 1 ? "Teste colagem de algodao." : "Combine formas e pintura livre.",
    toolProfile: "ei2",
    mode: index === 0 ? "livre" : "sugerido",
    status: "PUBLICADA",
    seededBy: "technical-pilot-v1",
  }));
  writeUniversalActivityState({ ...state, assignments: [...seeded, ...state.assignments] });
};

const renderUniversalActivityAssignDialog = () => `
  <dialog class="ua-dialog" data-ua-assign-dialog>
    <form method="dialog" class="ua-assign-form" data-ua-assign-form>
      <header><span>Atividade imprimivel</span><h2>Indicar atividade</h2><button type="button" data-ua-close-dialog aria-label="Fechar">×</button></header>
      ${renderPrintableContextPanel()}
      <input type="hidden" name="activityCode" />
      <label><span>Destino</span><select name="scope"><option value="class">Turma inteira</option><option value="group">Grupo de alunos</option><option value="student">Aluno individual</option></select></label>
      <label><span>Turma</span><select name="classId">${universalActivityDemoClasses.map((item) => `<option value="${printableEscape(item.id)}">${printableEscape(item.name)}</option>`).join("")}</select></label>
      <fieldset data-ua-students><legend>Alunos</legend></fieldset>
      <label><span>Orientação opcional</span><textarea name="instructions" rows="3" placeholder="Ex.: use pintura com dedo e cole bolinhas no desenho."></textarea></label>
      <label><span>Prazo opcional</span><input name="dueDate" type="date" /></label>
      <label><span>Perfil de ferramentas</span><select name="toolProfile"><option value="ei2">EI2</option><option value="ei3">EI3</option><option value="ei4">EI4</option><option value="ei5">EI5</option></select></label>
      <label><span>Modo</span><select name="mode"><option value="livre">Modo livre</option><option value="sugerido">Modo sugerido</option></select></label>
      <footer><button type="button" data-ua-close-dialog>Cancelar</button><button type="submit">Publicar atividade</button></footer>
    </form>
  </dialog>
`;

const renderStudentUniversalActivities = () => {
  seedUniversalActivityTechnicalAssignments();
  const assignments = getUniversalActivityAssignmentsForStudent();
  return `
    <section class="student-card ua-student-list" aria-labelledby="student-activities-title" data-ua-student-list>
      <div class="student-card-head"><h2 id="student-activities-title">Minhas Atividades</h2></div>
      <div class="ua-student-grid">
        ${
          assignments.length
            ? assignments
                .map((assignment) => {
                  const activity = getUniversalActivityByCode(assignment.activityCode);
                  const submission = getUniversalActivitySubmission(assignment.assignmentId);
                  const status = getUniversalActivityStudentStatus(assignment);
                  return `
                    <article class="ua-student-card">
                      <img src="${printableEscape(activity?.miniatura || activity?.arquivoA4 || "")}" alt="Atividade ${printableEscape(assignment.activityCode)}" loading="lazy" />
                      <div>
                        <mark>${printableEscape(assignment.activityCode)}</mark>
                        <strong>${printableEscape(activity?.titulo || assignment.activityCode)}</strong>
                        <small>Enviada em ${new Date(assignment.assignedAt).toLocaleDateString("pt-BR")}${assignment.dueDate ? ` · prazo ${new Date(assignment.dueDate).toLocaleDateString("pt-BR")}` : ""}</small>
                        <span>${status}</span>
                      </div>
                      <a href="motor-atividade.html?assignment=${encodeURIComponent(assignment.assignmentId)}">${status === "CONCLUIDA" ? "Ver minha atividade" : submission ? "Continuar" : "Comecar"}</a>
                    </article>
                  `;
                })
                .join("")
            : `<p class="ua-empty">Nenhuma atividade indicada para voce ainda.</p>`
        }
      </div>
    </section>
  `;
};

const renderStudentAvailableActivitiesCatalog = () => {
  const recommendedCodes = new Set(
    getStudentVisibleRecommendations({ activitiesOnly: true })
      .map((recommendation) => recommendation.contentId)
      .filter(Boolean)
  );
  const activities = printableActivitiesDataService
    .list({ admin: false })
    .filter((activity) => !recommendedCodes.has(activity.codigo))
    .slice(0, 12);
  if (!activities.length) {
    return `<p class="ua-empty">Nenhuma atividade disponivel no momento.</p>`;
  }
  return `
    <div class="ua-student-grid student-available-activities">
      ${activities
        .map((activity) => `
          <article class="ua-student-card">
            <img src="${printableEscape(activity.miniatura || activity.arquivoPng || activity.arquivoA4 || "")}" alt="Atividade ${printableEscape(activity.codigo)}" loading="lazy" />
            <div>
              <mark>${printableEscape(activity.codigo)}</mark>
              <strong>${printableEscape(activity.titulo || activity.codigo)}</strong>
              <small>${printableEscape(activity.idade || activity.faixaEtaria || "Educação Infantil")}</small>
              <span>${printableEscape(activity.tipo || activity.tiposAtividade?.[0] || "Atividade imprimivel")}</span>
            </div>
            <a href="atividades.html?codigo=${encodeURIComponent(activity.codigo)}&from=aluno">Abrir</a>
          </article>
        `)
        .join("")}
    </div>
  `;
};

const renderUniversalActivityStudentPortfolio = (studentId = universalActivityStudentProfile.id) => {
  const items = getUniversalActivityPortfolioForStudent(studentId);
  return `
    <section class="student-card ua-portfolio" aria-labelledby="student-portfolio-title" data-ua-portfolio>
      <div class="student-card-head"><h2 id="student-portfolio-title">Portfolio Digital</h2><span>${items.length} registros</span></div>
      <div class="ua-portfolio-grid">
        ${
          items.length
            ? items
                .map(({ submission, activity, assignment }) => `
                  <article>
                    <img src="${printableEscape(submission.finalArtwork || submission.preview || activity?.miniatura || "")}" alt="Portfolio ${printableEscape(activity?.titulo || submission.activityCode)}" loading="lazy" />
                    <div>
                      <mark>${printableEscape(submission.activityCode)}</mark>
                      <strong>${printableEscape(activity?.titulo || submission.activityCode)}</strong>
                      <small>${printableEscape(assignment?.className || submission.className)} · concluida em ${new Date(submission.completedAt).toLocaleDateString("pt-BR")}</small>
                    </div>
                  </article>
                `)
                .join("")
            : `<p class="ua-empty">As atividades concluidas aparecerao aqui automaticamente.</p>`
        }
      </div>
    </section>
  `;
};

const renderUniversalActivityTeacherPortfolio = () => {
  const state = readUniversalActivityState();
  const refs = state.portfolioRefs || [];
  const studentIds = [...new Set(refs.map((ref) => ref.studentId))];
  const findStudent = (studentId) =>
    universalActivityDemoClasses.flatMap((item) => item.students.map((student) => ({ ...student, className: item.name }))).find((student) => student.id === studentId);
  return `
    <section class="tw-board ua-portfolio-teacher">
      <div class="tw-section-head"><h2>Portfolio Digital</h2><span>${refs.length} atividades concluidas</span></div>
      ${
        studentIds.length
          ? studentIds
              .map((studentId) => {
                const student = findStudent(studentId);
                const items = getUniversalActivityPortfolioForStudent(studentId);
                return `
                  <article>
                    <header><strong>${printableEscape(student?.name || studentId)}</strong><small>${printableEscape(student?.className || "")} · ${items.length} registros</small></header>
                    <div>
                      ${items
                        .map(({ submission, activity }) => `
                          <figure>
                            <img src="${printableEscape(submission.finalArtwork || submission.preview || activity?.miniatura || "")}" alt="Atividade ${printableEscape(submission.activityCode)}" loading="lazy" />
                            <figcaption>${printableEscape(submission.activityCode)}</figcaption>
                          </figure>
                        `)
                        .join("")}
                    </div>
                  </article>
                `;
              })
              .join("")
          : `<p class="ua-empty">Nenhuma atividade concluida no portfolio ainda.</p>`
      }
    </section>
  `;
};

const renderUniversalActivityTeacherDeliveries = () => {
  const state = readUniversalActivityState();
  const assignments = state.assignments.filter((assignment) => assignment.status !== "ARQUIVADA" && !assignment.seededBy);
  return `
    <section class="tw-board ua-deliveries" data-ua-deliveries>
      <div class="tw-section-head"><h2>Atividades Indicadas</h2><button type="button" data-teacher-view="atividades">Indicar nova</button></div>
      ${
        assignments.length
          ? assignments
              .map((assignment) => {
                const activity = getUniversalActivityByCode(assignment.activityCode);
                const targetLabel = assignment.targetLabel || assignment.className || assignment.studentIds?.join(", ") || "Destinatário registrado";
                return `
                  <article class="ua-delivery-card">
                    <div>
                      <mark>${printableEscape(assignment.activityCode)}</mark>
                      <strong>${printableEscape(activity?.titulo || assignment.activityCode)}</strong>
                      <small>Destinatário: ${printableEscape(targetLabel)}</small>
                      ${assignment.assignedAt ? `<small>Indicada em ${new Date(assignment.assignedAt).toLocaleString("pt-BR")}</small>` : ""}
                      ${assignment.status ? `<small>Status: ${printableEscape(assignment.status)}</small>` : ""}
                    </div>
                    <button type="button" data-ua-open-delivery="${printableEscape(assignment.assignmentId)}">Consultar</button>
                  </article>
                `;
              })
              .join("")
          : `<p class="ua-empty">NENHUMA ATIVIDADE INDICADA AINDA.</p>`
      }
      <div class="ua-delivery-detail" data-ua-delivery-detail></div>
    </section>
  `;
};

const getTeacherTrackingData = () => {
  if (teacherInstitutionalState.status === "ready") {
    return { assignments: [], submissions: [], productions: [] };
  }
  const state = readUniversalActivityState();
  const assignments = (state.assignments || []).filter(
    (assignment) =>
      assignment &&
      assignment.status !== "ARQUIVADA" &&
      !assignment.seededBy &&
      assignment.classId === pilotProfiles.class.id
  );
  const assignmentIds = new Set(assignments.map((assignment) => assignment.assignmentId));
  const submissions = (state.submissions || []).filter(
    (submission) =>
      submission &&
      assignmentIds.has(submission.assignmentId) &&
      submission.studentId === pilotProfiles.student.id &&
      submission.status &&
      submission.status !== "NOT_STARTED"
  );
  const productions = submissions.filter((submission) => submission.preview || submission.finalArtwork || submission.completedAt);
  return { assignments, submissions, productions };
};

const renderTeacherTrackingAssignment = (assignment) => {
  const activity = getUniversalActivityByCode(assignment.activityCode);
  const submission = getUniversalActivitySubmission(assignment.assignmentId, pilotProfiles.student.id);
  const status = submission?.status || assignment.status || "INDICADA";
  const targetLabel = assignment.targetLabel || assignment.className || "Infantil 4 A";
  return `
    <article class="tw-tracking-item" data-teacher-search-item>
      <div>
        <span>${printableEscape(assignment.activityCode)}</span>
        <strong>${printableEscape(activity?.titulo || assignment.activityCode)}</strong>
        <small>Destinatário: ${printableEscape(targetLabel)}</small>
      </div>
      <mark>${printableEscape(status)}</mark>
    </article>
  `;
};

const renderTeacherTrackingProduction = (submission) => {
  const activity = getUniversalActivityByCode(submission.activityCode);
  return `
    <article class="tw-tracking-production" data-teacher-search-item>
      ${submission.finalArtwork || submission.preview ? `<img src="${printableEscape(submission.finalArtwork || submission.preview)}" alt="Produção registrada de ${printableEscape(pilotProfiles.student.name)}" loading="lazy" />` : ""}
      <div>
        <span>${printableEscape(submission.activityCode)}</span>
        <strong>${printableEscape(activity?.titulo || submission.activityCode)}</strong>
        ${submission.completedAt ? `<small>Registrada em ${new Date(submission.completedAt).toLocaleString("pt-BR")}</small>` : ""}
        ${submission.lastSavedAt && !submission.completedAt ? `<small>Última edição: ${new Date(submission.lastSavedAt).toLocaleString("pt-BR")}</small>` : ""}
      </div>
    </article>
  `;
};

const getTeacherTrackingPeriodDays = () => {
  const fromUrl = Number(getPrintableParams().get("period") || teacherTrackingState.periodDays || 30);
  return [7, 30, 90].includes(fromUrl) ? fromUrl : 30;
};

const getTeacherTrackingClassId = () => {
  const classes = getTeacherInstitutionalClasses();
  const fromUrl = getPrintableParams().get("class") || "";
  const candidate = fromUrl || teacherTrackingState.selectedClassId || classes[0]?.id || "";
  const selected = classes.some((classItem) => classItem.id === candidate) ? candidate : classes[0]?.id || "";
  teacherTrackingState.selectedClassId = selected;
  return selected;
};

const getTeacherTrackingStudentId = (classId = "") => {
  const students = getTeacherInstitutionalStudents(classId);
  const fromUrl = getPrintableParams().get("student") || "";
  const candidate = fromUrl || teacherTrackingState.selectedStudentId || students[0]?.id || "";
  const selected = students.some((student) => student.id === candidate) ? candidate : students[0]?.id || "";
  teacherTrackingState.selectedStudentId = selected;
  return selected;
};

const getTeacherTrackingStartDate = (periodDays = 30) => {
  const date = new Date();
  date.setDate(date.getDate() - Math.max(0, Number(periodDays || 30) - 1));
  return toTeacherIsoDate(date);
};

const getTeacherTrackingAttendanceKey = (classId = "", periodDays = 30) => `${classId}:${periodDays}:${getTeacherTrackingStartDate(periodDays)}`;

const getTeacherAnalyticsKey = (classId = "", periodDays = 30) => `${classId}:${periodDays}:${getTeacherTrackingStartDate(periodDays)}`;

const ensureTeacherTrackingAttendance = async ({ force = false, classId = "", periodDays = 30 } = {}) => {
  if (!classId) return teacherTrackingAttendanceState;
  const key = getTeacherTrackingAttendanceKey(classId, periodDays);
  if (!force && teacherTrackingAttendanceState.status === "ready" && teacherTrackingAttendanceState.key === key) return teacherTrackingAttendanceState;
  if (!force && teacherTrackingAttendanceState.promise && teacherTrackingAttendanceState.key === key) return teacherTrackingAttendanceState.promise;
  teacherTrackingAttendanceState.status = "loading";
  teacherTrackingAttendanceState.error = "";
  teacherTrackingAttendanceState.key = key;
  teacherTrackingAttendanceState.promise = (async () => {
    try {
      const client = createSupabaseRestClient();
      const startDate = getTeacherTrackingStartDate(periodDays);
      const rows = await client.request(
        "attendance_records",
        `?select=id,school_id,class_id,student_id,enrollment_id,attendance_date,status,notes,recorded_by,updated_by,updated_at&class_id=${supabaseEq(classId)}&attendance_date=gte.${encodeURIComponent(startDate)}&order=attendance_date.desc&order=student_id.asc&limit=1000`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      teacherTrackingAttendanceState.records = Array.isArray(rows) ? rows : [];
      teacherTrackingAttendanceState.status = "ready";
    } catch (error) {
      teacherTrackingAttendanceState.records = [];
      teacherTrackingAttendanceState.error = error.message || "Não foi possível carregar a frequência do periodo.";
      teacherTrackingAttendanceState.status = "error";
    } finally {
      teacherTrackingAttendanceState.promise = null;
    }
    return teacherTrackingAttendanceState;
  })();
  return teacherTrackingAttendanceState.promise;
};

const ensureTeacherClassAnalytics = async ({ force = false, classId = "", periodDays = 30 } = {}) => {
  if (!classId) return teacherAnalyticsState;
  const key = getTeacherAnalyticsKey(classId, periodDays);
  if (!force && teacherAnalyticsState.status === "ready" && teacherAnalyticsState.key === key) return teacherAnalyticsState;
  if (!force && teacherAnalyticsState.promise && teacherAnalyticsState.key === key) return teacherAnalyticsState.promise;
  teacherAnalyticsState.status = "loading";
  teacherAnalyticsState.error = "";
  teacherAnalyticsState.key = key;
  teacherAnalyticsState.promise = (async () => {
    try {
      const dateFrom = getTeacherTrackingStartDate(periodDays);
      const dateTo = toTeacherIsoDate(new Date());
      const [overview, attendanceTrend, assessmentTrend, comparison, alerts] = await Promise.all([
        analyticsService.getClassOverview({
          classId,
          dateFrom,
          dateTo,
        }),
        analyticsService.getTrendSeries({ classId, metric: "attendance_rate", dateFrom, dateTo, granularity: "week" }),
        analyticsService.getTrendSeries({ classId, metric: "assessment_average", dateFrom, dateTo, granularity: "week" }),
        analyticsService.getPeriodComparison({ classId, currentFrom: dateFrom, currentTo: dateTo }),
        analyticsService.getAlerts({ classId, dateFrom, dateTo }),
      ]);
      if (overview.error) throw new Error(overview.error);
      teacherAnalyticsState.result = {
        ...overview,
        trends: { attendance: attendanceTrend, assessment: assessmentTrend },
        comparison,
        alerts,
      };
      teacherAnalyticsState.status = "ready";
    } catch (error) {
      teacherAnalyticsState.result = null;
      teacherAnalyticsState.error = error.message || "Não foi possível carregar o Analytics da turma.";
      teacherAnalyticsState.status = "error";
    } finally {
      teacherAnalyticsState.promise = null;
    }
    return teacherAnalyticsState;
  })();
  return teacherAnalyticsState.promise;
};

const ensureTeacherTrackingBundle = async ({ force = false } = {}) => {
  await ensureTeacherInstitutionalData();
  if (teacherInstitutionalState.status !== "ready") return;
  const classId = getTeacherTrackingClassId();
  const periodDays = getTeacherTrackingPeriodDays();
  if (!classId) return;
  teacherTrackingState.periodDays = periodDays;
  await Promise.all([
    ensureTeacherTrackingAttendance({ force, classId, periodDays }),
    ensureTeacherClassAnalytics({ force, classId, periodDays }),
    ensureTeacherRecommendations({ force, classId }),
    ensureTeacherClassMessages({ force, classId }),
  ]);
};

const teacherTrackingPublishedRecommendations = (classId = "", studentId = "") =>
  (teacherRecommendationsState.items || []).filter(
    (item) =>
      item.classId === classId &&
      item.status === "published" &&
      (item.targetType === "class" || (studentId && item.targetType === "student" && item.studentId === studentId))
  );

const teacherTrackingAllPublishedRecommendations = (classId = "") =>
  (teacherRecommendationsState.items || []).filter((item) => item.classId === classId && item.status === "published");

const teacherTrackingPedagógicalMessages = (classId = "", studentId = "") =>
  (teacherClassMessagesState.messages || []).filter(
    (message) =>
      message.classId === classId &&
      message.status === "published" &&
      String(message.authorRole || "").toLowerCase() === "professor" &&
      (message.audienceType === "class" || (studentId && message.audienceType === "student" && message.studentId === studentId))
  );

const teacherTrackingAllPedagógicalMessages = (classId = "") =>
  (teacherClassMessagesState.messages || []).filter(
    (message) =>
      message.classId === classId &&
      message.status === "published" &&
      String(message.authorRole || "").toLowerCase() === "professor"
  );

const renderTeacherTrackingMetric = (label, value, detail, icon = "progresso") => `
  <article class="tw-tracking-metric">
    ${teacherInlineIcon(icon)}
    <div>
      <span>${printableEscape(label)}</span>
      <strong>${printableEscape(value)}</strong>
      <small>${printableEscape(detail)}</small>
    </div>
  </article>
`;

const renderTeacherTrackingRecommendation = (item) => `
  <article class="tw-tracking-item" data-teacher-search-item>
    <div>
      <span>${printableEscape(recommendationTypeLabel(item.contentType))}</span>
      <strong>${printableEscape(item.contentTitle)}</strong>
      <small>${item.targetType === "student" ? `Aluno: ${printableEscape(item.studentName || "Aluno")}` : `Turma: ${printableEscape(item.className || "Turma")}`}${item.note ? ` · ${printableEscape(item.note)}` : ""}</small>
    </div>
    <mark>${printableEscape(recommendationStatusLabel(item.status))}</mark>
  </article>
`;

const renderTeacherTrackingMessage = (message) => `
  <article class="tw-tracking-item" data-teacher-search-item>
    <div>
      <span>${message.audienceType === "student" ? "Recado individual" : "Recado da turma"}</span>
      <strong>${printableEscape(message.title)}</strong>
      <small>${printableEscape(message.date)}${message.studentName ? ` · ${printableEscape(message.studentName)}` : ""}</small>
    </div>
    <mark>Publicado</mark>
  </article>
`;

const renderTeacherTrackingAttendanceList = (records = [], studentsById = {}) => {
  if (teacherTrackingAttendanceState.status === "loading") return `<p class="ua-empty">CARREGANDO FREQUENCIA.</p>`;
  if (teacherTrackingAttendanceState.status === "error") return `<p class="ua-empty">${printableEscape(teacherTrackingAttendanceState.error)}</p>`;
  if (!records.length) return `<p class="ua-empty">SEM REGISTROS DE FREQUENCIA NO PERIODO.</p>`;
  return records
    .slice(0, 8)
    .map((record) => {
      const student = studentsById[record.student_id] || {};
      return `
        <article class="tw-tracking-item" data-teacher-search-item>
          <div>
            <span>${printableEscape(record.attendance_date || "Data")}</span>
            <strong>${printableEscape(student.name || "Aluno")}</strong>
            <small>${record.notes ? printableEscape(record.notes) : "Sem observação"}</small>
          </div>
          <mark>${printableEscape(attendanceStatusLabel(record.status))}</mark>
        </article>
      `;
    })
    .join("");
};

const renderTeacherTrackingView = () => {
  const { assignments, submissions, productions } = getTeacherTrackingData();
  const statuses = [...new Set(submissions.map((submission) => submission.status).filter(Boolean))];
  const institutionalReady = teacherInstitutionalState.status === "ready";
  const classes = getTeacherInstitutionalClasses();
  const selectedClassId = institutionalReady ? getTeacherTrackingClassId() : "";
  const selectedClass = classes.find((classItem) => classItem.id === selectedClassId) || classes[0] || null;
  const students = selectedClass ? getTeacherInstitutionalStudents(selectedClass.id) : [];
  const selectedStudentId = institutionalReady && selectedClass ? getTeacherTrackingStudentId(selectedClass.id) : "";
  const selectedStudent = students.find((student) => student.id === selectedStudentId) || students[0] || null;
  const periodDays = getTeacherTrackingPeriodDays();
  const attendanceRecords = selectedClass ? (teacherTrackingAttendanceState.records || []).filter((record) => record.class_id === selectedClass.id) : [];
  const studentAttendance = selectedStudent ? attendanceRecords.filter((record) => record.student_id === selectedStudent.id) : [];
  const classAttendance = attendanceSummary(attendanceRecords);
  const selectedAttendance = attendanceSummary(studentAttendance);
  const analyticsResult = teacherAnalyticsState.status === "ready" && teacherAnalyticsState.key === getTeacherAnalyticsKey(selectedClass?.id || "", periodDays)
    ? teacherAnalyticsState.result || {}
    : {};
  const analyticsSummary = analyticsResult.summary || {};
  const analyticsAssessment = analyticsResult.assessment || {};
  const analyticsBncc = analyticsResult.bncc || [];
  const analyticsTrends = analyticsResult.trends || {};
  const analyticsAlerts = analyticsResult.alerts?.alerts || [];
  const studentById = Object.fromEntries(students.map((student) => [student.id, student]));
  const allRecommendations = selectedClass ? teacherTrackingAllPublishedRecommendations(selectedClass.id) : [];
  const recommendations = selectedClass ? teacherTrackingPublishedRecommendations(selectedClass.id, selectedStudent?.id || "") : [];
  const classRecommendations = recommendations.filter((item) => item.targetType === "class");
  const studentRecommendations = selectedStudent ? recommendations.filter((item) => item.targetType === "student" && item.studentId === selectedStudent.id) : [];
  const allMessages = selectedClass ? teacherTrackingAllPedagógicalMessages(selectedClass.id) : [];
  const messages = selectedClass ? teacherTrackingPedagógicalMessages(selectedClass.id, selectedStudent?.id || "") : [];
  const classMessages = messages.filter((item) => item.audienceType === "class");
  const studentMessages = selectedStudent ? messages.filter((item) => item.audienceType === "student" && item.studentId === selectedStudent.id) : [];
  if (institutionalReady) {
    return `
      <section class="tw-board tw-tracking-shell">
        <div class="tw-planning-heading">
          <div>
            <span>Acompanhamento</span>
            <h2>Acompanhamento</h2>
            <p>Leitura pedagógica por turma e aluno, usando apenas registros reais disponiveis.</p>
          </div>
          <div class="tw-tracking-filters">
            <label class="tw-class-selector">
              <span>Turma</span>
              <select data-tracking-class>
                ${classes.map((classItem) => `<option value="${printableEscape(classItem.id)}" ${classItem.id === selectedClass?.id ? "selected" : ""}>${printableEscape(classItem.name)}</option>`).join("")}
              </select>
            </label>
            <label class="tw-class-selector">
              <span>Aluno</span>
              <select data-tracking-student>
                ${students.map((student) => `<option value="${printableEscape(student.id)}" ${student.id === selectedStudent?.id ? "selected" : ""}>${printableEscape(student.name)}</option>`).join("")}
              </select>
            </label>
            <label class="tw-class-selector">
              <span>Período</span>
              <select data-tracking-period>
                ${[7, 30, 90].map((days) => `<option value="${days}" ${days === periodDays ? "selected" : ""}>Ultimos ${days} dias</option>`).join("")}
              </select>
            </label>
          </div>
        </div>
        ${
          selectedClass
            ? `<div class="tw-tracking-summary" aria-label="Visão geral da turma">
                ${renderTeacherTrackingMetric("Turma", selectedClass.name, selectedClass.schoolName || selectedClass.shift || "Turma institucional", "turmas")}
                ${renderTeacherTrackingMetric("Alunos", String(students.length), "Matrículas ativas da turma", "alunos")}
                ${renderTeacherTrackingMetric("Presenca", `${classAttendance.percent}%`, `${classAttendance.present} presenças · ${classAttendance.absent} faltas · ${classAttendance.justified} justificadas`, "frequencia")}
                ${renderTeacherTrackingMetric("Avalia+", analyticsPercentLabel(analyticsSummary.assessment_average), `${analyticsNumberLabel(analyticsAssessment.completed_students)} entrega(s) · ${analyticsPercentLabel(analyticsSummary.assessment_participation)} participação`, "chart")}
                ${renderTeacherTrackingMetric("BNCC", analyticsNumberLabel(analyticsSummary.bncc_skills), "Habilidades avaliadas no período", "chart")}
                ${renderTeacherTrackingMetric("Recomendações", String(allRecommendations.length), "Publicadas para a turma e seus alunos", "biblioteca")}
                ${renderTeacherTrackingMetric("Recados", String(allMessages.length), "Mensagens pedagógicas da turma", "comunicados")}
              </div>`
            : renderTeacherEmptyState("NENHUMA TURMA INSTITUCIONAL DISPONIVEL.")
        }
      </section>
      <div class="tw-tracking-grid">
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Alunos da turma</h2><span>${students.length} alunos</span></div>
          <div class="tw-tracking-students">
            ${students.length ? students.map((student) => `
              <button type="button" class="tw-student-card ${student.id === selectedStudent?.id ? "is-active" : ""}" data-tracking-student-pick="${printableEscape(student.id)}" data-teacher-search-item>
                ${student.avatar ? `<img class="tw-student-avatar" src="${printableEscape(student.avatar)}" alt="" loading="lazy" />` : `<span>${student.name.split(" ").map((part) => part[0]).slice(0, 2).join("")}</span>`}
                <div>
                  <strong>${printableEscape(student.name)}</strong>
                  <small>${printableEscape(student.className)} · ${printableEscape(student.enrollmentStatus || "Matrícula ativa")}</small>
                </div>
              </button>
            `).join("") : renderTeacherEmptyState("NENHUM ALUNO VINCULADO A ESTA TURMA.")}
          </div>
        </section>
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Ficha pedagógica</h2><span>${selectedStudent ? printableEscape(selectedStudent.name) : "Aluno"}</span></div>
          ${
            selectedStudent
              ? `<div class="tw-tracking-student-detail">
                  <article><span>Identificação</span><strong>${printableEscape(selectedStudent.name)}</strong><small>${printableEscape(selectedClass.name)} · ${printableEscape(selectedClass.schoolName || "Escola")}</small></article>
                  <article><span>Frequência no periodo</span><strong>${selectedAttendance.percent}%</strong><small>${selectedAttendance.present} presenças · ${selectedAttendance.absent} faltas · ${selectedAttendance.justified} justificadas</small></article>
                  <article><span>Recomendações</span><strong>${classRecommendations.length + studentRecommendations.length}</strong><small>${studentRecommendations.length} individual(is) e ${classRecommendations.length} da turma</small></article>
                  <article><span>Recados</span><strong>${classMessages.length + studentMessages.length}</strong><small>${studentMessages.length} individual(is) e ${classMessages.length} da turma</small></article>
                </div>`
              : renderTeacherEmptyState("SELECIONE UM ALUNO PARA VER O ACOMPANHAMENTO.")
          }
        </section>
      </div>
      <div class="tw-tracking-grid is-wide">
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Frequência</h2><span>Ultimos ${periodDays} dias</span></div>
          <div class="tw-tracking-list">${renderTeacherTrackingAttendanceList(attendanceRecords, studentById)}</div>
        </section>
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Recomendações publicadas</h2><button type="button" data-teacher-view="atividades">Indicar atividade</button></div>
          <div class="tw-tracking-list">${allRecommendations.length ? allRecommendations.map(renderTeacherTrackingRecommendation).join("") : `<p class="ua-empty">NENHUMA RECOMENDACAO PUBLICADA PARA ESTE CONTEXTO.</p>`}</div>
        </section>
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Recados pedagógicos</h2><button type="button" data-teacher-open-url="${selectedClass ? `${getTeacherClassHref(selectedClass)}?tab=recados` : "professor.html?view=turmas"}">Abrir recados</button></div>
          <div class="tw-tracking-list">${allMessages.length ? allMessages.slice(0, 6).map(renderTeacherTrackingMessage).join("") : `<p class="ua-empty">NENHUM RECADO PEDAGOGICO PUBLICADO PARA ESTE CONTEXTO.</p>`}</div>
        </section>
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Analytics da turma</h2><span>Ultimos ${periodDays} dias</span></div>
          ${
            teacherAnalyticsState.status === "loading"
              ? `<p class="ua-empty">CARREGANDO INDICADORES DA TURMA.</p>`
              : teacherAnalyticsState.status === "error"
                ? `<p class="ua-empty">${printableEscape(teacherAnalyticsState.error)}</p>`
                : `<div class="tw-tracking-list">
                    <article class="tw-tracking-item"><div><span>Frequência</span><strong>${analyticsPercentLabel(analyticsSummary.attendance_rate)}</strong><small>Presenças sobre registros reais</small></div><mark>${analyticsNumberLabel(analyticsResult.attendance?.total_records)} registros</mark></article>
                    <article class="tw-tracking-item"><div><span>Avalia+</span><strong>${analyticsPercentLabel(analyticsSummary.assessment_average)}</strong><small>${analyticsNumberLabel(analyticsAssessment.completed_students)} entrega(s) no período</small></div><mark>${analyticsPercentLabel(analyticsSummary.assessment_participation)}</mark></article>
                    <article class="tw-tracking-item"><div><span>BNCC</span><strong>${analyticsNumberLabel(analyticsSummary.bncc_skills)} habilidade(s)</strong><small>${analyticsBncc.slice(0, 3).map((skill) => `${skill.bncc_skill}: ${analyticsPercentLabel(skill.percentage)}`).join(" · ") || "Aguardando resultados"}</small></div><mark>Sem ranking</mark></article>
                    <article class="tw-tracking-item"><div><span>Tendência</span><strong>${analyticsTrends.attendance?.has_trend ? analyticsDeltaLabel(analyticsTrends.attendance.delta_absolute) : "Sem tendência"}</strong><small>${htmlEscape(analyticsTrends.attendance?.message || "Dados insuficientes para comparar períodos.")}</small></div><mark>Frequência</mark></article>
                    <article class="tw-tracking-item"><div><span>Alertas</span><strong>${analyticsNumberLabel(analyticsAlerts.length)}</strong><small>${analyticsAlerts.slice(0, 2).map((alert) => printableEscape(alert.message || "")).join(" · ") || "Nenhum alerta pelos limiares definidos"}</small></div><mark>Acompanhamento</mark></article>
                  </div>`
          }
        </section>
      </div>
      <div class="tw-tracking-grid">
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Atividades e progresso</h2><span>Preparado</span></div>
          <p class="ua-empty">AINDA NAO HA FONTE INSTITUCIONAL DE PROGRESSO DE ATIVIDADES CONECTADA A ESTA VISAO.</p>
        </section>
        <section class="tw-board tw-tracking-section">
          <div class="tw-section-head"><h2>Observacoes pedagógicas</h2><span>Preparado</span></div>
          <p class="ua-empty">As observacoes pedagógicas estruturadas aparecerao aqui quando estiverem disponiveis.</p>
        </section>
      </div>
    `;
  }
  if (teacherInstitutionalState.status === "loading") {
    return `<section class="tw-board">${renderTeacherInstitutionalStatus("CARREGANDO ACOMPANHAMENTO INSTITUCIONAL.")}</section>`;
  }
  if (teacherInstitutionalState.status === "error") {
    return `<section class="tw-board">${renderTeacherInstitutionalStatus(teacherInstitutionalState.error || "NAO FOI POSSIVEL CARREGAR ACOMPANHAMENTO.")}</section>`;
  }
  return `
    <section class="tw-board tw-tracking-shell">
      <div class="tw-planning-heading">
        <div>
          <span>Acompanhamento</span>
          <h2>Acompanhamento</h2>
          <p>ACOMPANHE OS REGISTROS E AS EXPERIENCIAS DA SUA TURMA.</p>
        </div>
        <label class="tw-class-selector">
          <span>Turma</span>
          <select data-tracking-class>
            <option value="${printableEscape(pilotProfiles.class.id)}">${printableEscape(pilotProfiles.class.name)}</option>
          </select>
        </label>
      </div>
      <div class="tw-tracking-summary" aria-label="Visão geral da turma">
        <article><span>Turma</span><strong>${printableEscape(pilotProfiles.class.name)}</strong><small>${printableEscape(pilotProfiles.class.shift || "Turma piloto")}</small></article>
        <article><span>Alunos</span><strong>${teacherWorkspaceStudents.length}</strong><small>Alunos vinculados a turma</small></article>
        <article><span>Atividades indicadas</span><strong>${assignments.length}</strong><small>Registros disponiveis</small></article>
        <article><span>Produções</span><strong>${productions.length}</strong><small>Produções registradas</small></article>
      </div>
    </section>
    <section class="tw-board tw-tracking-section">
      <div class="tw-section-head"><h2>Alunos</h2><span>${printableEscape(pilotProfiles.class.name)}</span></div>
      <div class="tw-tracking-students">
        ${teacherWorkspaceStudents.map(renderStudentCard).join("")}
      </div>
    </section>
    <section class="tw-board tw-tracking-section" data-ua-deliveries>
      <div class="tw-section-head"><h2>Atividades Indicadas</h2><button type="button" data-teacher-view="atividades">Indicar atividade</button></div>
      <div class="tw-tracking-list">
        ${assignments.length ? assignments.map(renderTeacherTrackingAssignment).join("") : `<p class="ua-empty">NENHUMA ATIVIDADE INDICADA AINDA.</p>`}
      </div>
      <div class="ua-delivery-detail" data-ua-delivery-detail></div>
    </section>
    <section class="tw-board tw-tracking-section">
      <div class="tw-section-head"><h2>Produções</h2><span>Registros da turma</span></div>
      <div class="tw-tracking-list">
        ${productions.length ? productions.map(renderTeacherTrackingProduction).join("") : `<p class="ua-empty">AINDA NAO HA PRODUCOES REGISTRADAS.</p>`}
      </div>
    </section>
    <section class="tw-board tw-tracking-section">
      <div class="tw-section-head"><h2>Progresso</h2><span>Estados registrados</span></div>
      ${
        statuses.length
          ? `<div class="tw-tracking-status-list">${statuses.map((status) => `<span>${printableEscape(status)}</span>`).join("")}</div>`
          : `<p class="ua-empty">O PROGRESSO APARECERA AQUI QUANDO HOUVER REGISTROS.</p>`
      }
    </section>
    <section class="tw-board tw-tracking-section">
      <div class="tw-section-head"><h2>Registros Pedagógicos</h2><span>Preparado</span></div>
      <p class="ua-empty">NENHUM REGISTRO PEDAGOGICO DISPONIVEL.</p>
    </section>
    <section class="tw-board tw-tracking-section">
      <div class="tw-section-head"><h2>Relatórios</h2><span>Futuro</span></div>
      <p class="ua-empty">RELATORIOS SERAO GERADOS FUTURAMENTE A PARTIR DE REGISTROS REAIS.</p>
    </section>
  `;
};

