const renderTeacherFamilyMessagesView = () => {
  if (teacherInstitutionalState.status !== "ready") {
    return `<section class="tw-board">${renderTeacherInstitutionalStatus("CARREGANDO VINCULOS INSTITUCIONAIS.")}</section>`;
  }
  const classes = getTeacherInstitutionalClasses();
  const messages = teacherClassMessagesState.messages || [];
  return `
    <section class="tw-board tw-messages-shell">
      <div class="tw-section-head">
        <div>
          <span>Mensagens</span>
          <h2>Recados para a turma</h2>
        </div>
        <button type="button" data-teacher-view="inicio">Voltar</button>
      </div>
      <form class="tw-planning-form" data-teacher-family-message-form>
        <label>
          <span>Turma</span>
          <select name="classId" required>
            ${
              classes.length
                ? classes.map((classItem) => `<option value="${printableEscape(classItem.id)}" ${classItem.id === teacherClassMessagesState.classId ? "selected" : ""}>${printableEscape(classItem.name)} · ${printableEscape(classItem.schoolName || "Escola")}</option>`).join("")
                : `<option value="">Nenhuma turma autorizada</option>`
            }
          </select>
        </label>
        <label>
          <span>Data na semana</span>
          <input name="entryDate" type="date" required value="${printableEscape(teacherClassMessagesState.weekStartIso || getTeacherPlanningWeekStart())}" />
        </label>
        <label>
          <span>Titulo do recado</span>
          <input name="title" required maxlength="90" placeholder="Ex.: Recado para a turma" />
        </label>
        <label class="tw-planning-form-note">
          <span>Mensagem</span>
          <textarea name="message" rows="4" required maxlength="700" placeholder="Escreva o comunicado que aparecera na Minha Semana."></textarea>
        </label>
        <div class="tw-planning-form-actions">
          <button type="submit" ${classes.length ? "" : "disabled"}>PUBLICAR NA MINHA SEMANA</button>
        </div>
      </form>
      ${renderTeacherClassWeeklyBoard()}
      <div class="tw-section-head">
        <h2>Comunicados publicados</h2>
        <span>${teacherClassMessagesState.status === "ready" ? `${messages.length} registro${messages.length === 1 ? "" : "s"}` : "Carregando"}</span>
      </div>
      ${
        teacherClassMessagesState.status === "loading"
          ? renderTeacherInstitutionalStatus("CARREGANDO RECADOS.")
          : teacherClassMessagesState.status === "error"
            ? renderTeacherEmptyState("NAO FOI POSSIVEL CARREGAR OS RECADOS.", teacherClassMessagesState.error)
            : messages.length
              ? `<div class="tw-planning-list">${messages
                  .map(
                    (message) => `
                      <article class="tw-planning-proposal" data-teacher-search-item>
                        <span>${printableEscape(message.className)} · ${printableEscape(message.date)} · MINHA SEMANA</span>
                        <strong>${printableEscape(message.title)}</strong>
                        <small>${printableEscape(message.text)}</small>
                      </article>
                    `
                  )
                  .join("")}</div>`
              : renderTeacherEmptyState("NENHUM RECADO PUBLICADO AINDA.", "Os comunicados enviados para a turma aparecerao na Minha Semana.")
      }
    </section>
  `;
};

const renderUniversalActivityMotorPage = () => {
  seedUniversalActivityTechnicalAssignments();
  const assignmentId = getPrintableParams().get("assignment");
  const state = readUniversalActivityState();
  const assignment = state.assignments.find((item) => item.assignmentId === assignmentId);
  if (!assignment || !assignment.studentIds.includes(universalActivityStudentProfile.id)) {
    return `<section class="ua-motor-shell"><div class="pa-empty"><h1>Atividade nao encontrada</h1><p>Esta atividade nao esta atribuida ao aluno atual.</p><a href="aluno.html">Voltar</a></div></section>`;
  }
  const activity = getUniversalActivityByCode(assignment.activityCode);
  if (!activity) {
    return `<section class="ua-motor-shell"><div class="pa-empty"><h1>Base nao encontrada</h1><p>O codigo ${printableEscape(assignment.activityCode)} não existe no Banco de Atividades.</p><a href="aluno.html">Voltar</a></div></section>`;
  }
  getOrCreateUniversalActivitySubmission(assignment);
  const tools = getUniversalActivityTools(activity, assignment);
  const suggestedTools = assignment.mode === "sugerido" ? getUniversalActivitySuggestedTools(activity).filter((tool) => tools.includes(tool)) : [];
  const colors = ["#0b7a34", "#e53935", "#1e88e5", "#fdd835", "#fb8c00", "#8e24aa", "#111111", "#ffffff"];
  return `
    <section class="ua-motor-shell" data-ua-engine data-assignment-id="${printableEscape(assignment.assignmentId)}">
      <header class="ua-motor-head">
        <a href="aluno.html">Voltar</a>
        <div><span>${printableEscape(activity.codigo)}</span><h1>${printableEscape(activity.titulo)}</h1><small>${printableEscape(assignment.instructions || "Crie do seu jeito.")}</small></div>
        <button type="button" data-ua-complete>Concluir</button>
      </header>
      <main class="ua-motor-layout">
        <aside class="ua-tools" aria-label="Ferramentas">
          ${tools.map((tool) => `<button type="button" data-ua-tool="${tool}" class="${[tool === "pincel" ? "is-active" : "", suggestedTools.includes(tool) ? "is-suggested" : ""].filter(Boolean).join(" ")}"><span>${universalActivityToolLabels[tool] || tool}</span></button>`).join("")}
        </aside>
        <section class="ua-stage-wrap">
          <div class="ua-stage" data-ua-stage>
            <img src="${printableEscape(activity.arquivoA4 || activity.arquivoOriginal)}" alt="Atividade base ${printableEscape(activity.codigo)}" data-ua-base />
            <canvas data-ua-canvas width="1600" height="1131"></canvas>
            <div class="ua-object-layer" data-ua-object-layer></div>
          </div>
        </section>
        <aside class="ua-controls" aria-label="Controles">
          <div class="ua-palette">${colors.map((color, index) => `<button type="button" data-ua-color="${color}" style="--ua-color:${color}" aria-label="Cor ${index + 1}" class="${index === 0 ? "is-active" : ""}"></button>`).join("")}</div>
          <label><span>Espessura</span><input type="range" min="6" max="44" value="16" data-ua-size /></label>
          <button type="button" data-ua-undo>Desfazer</button>
          <button type="button" data-ua-redo>Refazer</button>
          <button type="button" data-ua-clear>Limpar</button>
          <button type="button" data-ua-save>Salvar</button>
          <output data-ua-save-status>Salvo automaticamente</output>
        </aside>
      </main>
    </section>
  `;
};

