const adminOperationalState = {
  status: "idle",
  error: "",
  data: null,
};

const ensureAdminSupabaseConfig = async () => {
  if (typeof window === "undefined" || window.RAIZES_SUPABASE?.url) return;
  await new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = `supabase-config.js?v=admin-ti-v1-fase01-20260906d-${Date.now()}`;
    script.onload = () => (window.RAIZES_SUPABASE?.url ? resolve() : reject(new Error("Configuração do Supabase nao foi carregada.")));
    script.onerror = () => reject(new Error("Não foi possível carregar supabase-config.js."));
    document.head.appendChild(script);
  });
};

const countRows = (rows) => (Array.isArray(rows) ? rows.length : 0);
const countActiveRows = (rows) =>
  (Array.isArray(rows) ? rows : []).filter((row) => String(row.status || row.membership_status || "").toLowerCase() !== "inactive").length;

const ensureAdminReadOnlyData = async ({ force = false } = {}) => {
  if (!force && adminOperationalState.status === "ready") return adminOperationalState;
  if (!force && adminOperationalState.promise) return adminOperationalState.promise;
  adminOperationalState.status = "loading";
  adminOperationalState.error = "";
  adminOperationalState.promise = (async () => {
    try {
      await ensureAdminSupabaseConfig();
      const client = createSupabaseRestClient();
      const context = await client.getContext({ requireAuthenticated: true, allowedRoles: ["admin"] });
      const options = { requireAuthenticated: true, allowedRoles: ["admin"] };
      const [
        schools,
        authUsers,
        profiles,
        teachers,
        students,
        guardians,
        classes,
        enrollments,
        schoolMemberships,
        classTeacherMemberships,
        studentGuardianLinks,
        installations,
        contentAvailability,
        communications,
      ] = await Promise.all([
        client.request("schools", "?select=id,nome,codigo_inep,municipio,estado,diretor,status&order=nome.asc", options),
        client.request("rpc/admin_list_auth_users", "", { ...options, method: "POST", body: "{}" }).catch(() => []),
        client.request("rpc/secretaria_list_staff_profiles", "", { ...options, method: "POST", body: "{}" }).catch(() =>
          client.request("profiles", "?select=id,display_name,platform_role,status&order=display_name.asc", options)
        ),
        client.request("rpc/secretaria_list_teachers", "", { ...options, method: "POST", body: "{}" }).catch(() =>
          client.request("teachers", "?select=id,user_id,school_id,profile_id,disciplina,status", options).catch(() => [])
        ),
        client.request("rpc/secretaria_list_students", "", { ...options, method: "POST", body: "{}" }).catch(() =>
          client.request("students", "?select=id,school_id,class_id,user_id,nome,email,status&order=nome.asc", options).catch(() => [])
        ),
        client.request("guardians", "?select=id,school_id,profile_id,full_name,email,phone,status,access_status,created_at&order=full_name.asc", options).catch(() => []),
        client.request("rpc/secretaria_list_classes", "", { ...options, method: "POST", body: "{}" }).catch(() =>
          client.request("classes", "?select=id,school_id,nome,status,school_year&order=nome.asc", options).catch(() => [])
        ),
        client.request("rpc/secretaria_list_enrollments", "", { ...options, method: "POST", body: "{}" }).catch(() =>
          client.request("enrollments", "?select=id,school_id,class_id,student_id,status,school_year&order=created_at.desc", options).catch(() => [])
        ),
        client.request("school_memberships", "?select=id,school_id,profile_id,membership_role,status,started_at,ended_at&order=started_at.desc", options).catch(() => []),
        client.request("rpc/secretaria_list_class_teacher_memberships", "", { ...options, method: "POST", body: "{}" }).catch(() => []),
        client.request("student_guardian_links", "?select=id,student_id,guardian_id,relationship,is_primary,status,created_at&order=created_at.asc", options).catch(() => []),
        client.request("rs_school_installations", "?select=id,school_id,school_code,deployment_mode,schema_version,package_version,school_year,current_stage,validation_status,created_at,updated_at&order=created_at.desc", options).catch(() => []),
        client.request("school_content_availability", "?select=id,school_id,content_type,content_id,status,available_from,available_until,deleted_at,created_at,updated_at&order=updated_at.desc", options).catch(() => []),
        client.request("communications", "?select=id,school_id,status,audience_type,created_at&order=created_at.desc", options),
      ]);
      adminOperationalState.status = "ready";
      adminOperationalState.data = {
        context,
        schools: schools || [],
        authUsers: authUsers || [],
        profiles: profiles || [],
        teachers: teachers || [],
        students: students || [],
        guardians: guardians || [],
        classes: classes || [],
        enrollments: enrollments || [],
        schoolMemberships: schoolMemberships || [],
        classTeacherMemberships: classTeacherMemberships || [],
        studentGuardianLinks: studentGuardianLinks || [],
        installations: installations || [],
        contentAvailability: contentAvailability || [],
        communications: communications || [],
      };
      return adminOperationalState;
    } catch (error) {
      adminOperationalState.status = "error";
      adminOperationalState.error = error.message || "Não foi possível carregar o painel Admin.";
      adminOperationalState.data = null;
      return adminOperationalState;
    } finally {
      adminOperationalState.promise = null;
    }
  })();
  return adminOperationalState.promise;
};

