        const attrs = tab.view ? `href="#${tab.view}" data-admin-view="${tab.view}"` : `href="${tab.href}"`;
        return `<a ${attrs} class="${isActive ? "is-active" : ""}" data-status="${tab.status}">${tab.label}</a>`;
