const secretariaLink = (view, extra = {}) => {
  const params = new URLSearchParams();
  params.set("view", view);
  Object.entries(extra).forEach(([key, value]) => {
    if (value) params.set(key, value);
  });
  return `secretaria.html?${params.toString()}`;
};
